// Bill discrepancies — parse an order export and/or a supplier bill statement.
// Bills are persisted so SKU links, aliases and applied costs survive.
export const checkBillDiscrepancies = (formData) =>
  api.post('/billing/discrepancies', formData, { headers: { 'Content-Type': 'multipart/form-data' } }).then(r => r.data)
export const getPurchaseBills = () => api.get('/billing/purchase-bills').then(r => r.data)
export const linkBillLine = (lineId, { sku_id, pack_multiple = 1, remember = true }) =>
  api.post(`/billing/purchase-bills/lines/${lineId}/link`, null,
    { params: { sku_id, pack_multiple, remember } }).then(r => r.data)
export const applyBillCost = (lineId) =>
  api.post(`/billing/purchase-bills/lines/${lineId}/apply-cost`).then(r => r.data)

export default api
/**
 * Safe message from an axios error.
 *
 * FastAPI returns `detail` as a plain string for HTTPException but as an ARRAY of
 * {type, loc, msg, input} objects for validation errors. Passing that array
 * straight into state and rendering it crashes React with "Objects are not valid
 * as a React child" — which is exactly how the Team page went blank in group mode.
 */
export function errText(e, fallback = 'Something went wrong') {
  const d = e?.response?.data?.detail
  if (typeof d === 'string') return d
  if (Array.isArray(d)) return d.map(x => x?.msg).filter(Boolean).join('; ') || fallback
  if (d && typeof d === 'object') return d.msg || d.detail || fallback
  return e?.message || fallback
}

/**
 * BidirectionalPctAmount
 * ──────────────────────────────────────────────────────────────────────
 * Renders a bidirectional `% ↔ ₹` pair of cells in a table row.
 * Used for CR, Damage, Profit (and future: Tier, AD).
 *
 * Behaviour:
 *  • Edit % → ₹ auto-derives from anchor (handled by parent onUpd; we just
 *    clear the ₹ field and store the typed %).
 *  • Edit ₹ → % auto-derives (parent computes from ₹ ÷ anchor × 100).
 *  • Master stored value = whichever was last typed; the other is computed.
 *
 * The component is dumb about the math — it only:
 *  • Shows two inputs
 *  • On change, calls onUpd({ [pctKey]: x, [amtKey]: '' }) or vice-versa
 *  • Renders computed value as placeholder when input is empty
 *
 * Anchors live in the parent's compute() function; see logic.md §4.
 */
export default function BidirectionalPctAmount({
  pctKey,
  amtKey,
  pctValue,
  amtValue,
  pctComputed,
  amtComputed,
  onUpd,
  pctVisible = true,
  amtVisible = true,
  pctClassName = '',
  amtClassName = '',
  shadeClassName = '',
  size = 1,
}) {
  return (
    <>
      {pctVisible && (
        <td className={`ec ${pctClassName} ${shadeClassName}`}>
          <div className="ec-sizer-wrap">
            <span className="ec-sizer mono">{pctValue || pctComputed}</span>
            <input
              className="ec-input right mono"
              type="number"
              size={size}
              value={pctValue}
              placeholder={pctComputed}
              onChange={e => onUpd({ [pctKey]: e.target.value, [amtKey]: '' })}
              onBlur={e => {
                // Round to 2 decimals on blur — keeps stored value clean
                const v = parseFloat(e.target.value)
                if (Number.isFinite(v)) onUpd({ [pctKey]: String(+v.toFixed(2)), [amtKey]: '' })
              }}
            />
          </div>
        </td>
      )}
      {amtVisible && (
        <td className={`ec ${amtClassName} ${shadeClassName}`}>
          <div className="ec-sizer-wrap">
            <span className="ec-sizer mono">{amtValue || amtComputed}</span>
            <input
              className="ec-input right mono"
              type="number"
              size={size}
              value={amtValue}
              placeholder={amtComputed}
              onChange={e => onUpd({ [pctKey]: '', [amtKey]: e.target.value })}
              onBlur={e => {
                const v = parseFloat(e.target.value)
                if (Number.isFinite(v)) onUpd({ [pctKey]: '', [amtKey]: String(+v.toFixed(2)) })
              }}
            />
          </div>
        </td>
      )}
    </>
  )
}

import { useState, useEffect, useMemo } from 'react'
import SmartCell from './SmartCell'
import {
  checkBillDiscrepancies, getPurchaseBills, linkBillLine, applyBillCost,
  getSkus, errText,
} from '../api/client'

/**
 * Bill Discrepancies — supplier bills against our own SKU costs.
 *
 * Bills (what we BOUGHT) are saved; the Flipkart order list (what we SOLD) is
 * only displayed, since the two are opposite sides of the business and share no
 * key. No figure is ever calculated across the two files.
 *
 * The cost check is: bill rate ÷ pack multiple = unit cost, compared against the
 * SKU's recorded Product Cost. The pack multiple is explicit — a ₹90 box of 6 is
 * ₹15 a glass, and guessing that from the SKU code would invent a discrepancy.
 */
const money = n => (n == null ? '—' : `₹${Number(n).toLocaleString('en-IN')}`)

function Flag({ children, tone = 'warn' }) {
  return <span className={`bd-flag bd-${tone}`}>{children}</span>
}

function Upload({ label, hint, accept, file, onPick }) {
  return (
    <div className="bd-pick">
      <span className="bd-pick-label">{label} <small>{hint}</small></span>
      <div className="bd-pick-row">
        <label className="bd-btn">
          {file ? 'Change file' : 'Choose file'}
          <input type="file" accept={accept}
            onChange={e => onPick(e.target.files?.[0] || null)} />
        </label>
        <span className={`bd-fname${file ? ' on' : ''}`}>{file ? file.name : 'No file chosen'}</span>
        {file && <button className="bd-clear" onClick={() => onPick(null)} aria-label="Remove file">✕</button>}
      </div>
    </div>
  )
}

export default function BillDiscrepancies() {
  const [ordersFile, setOrdersFile] = useState(null)
  const [billsFile,  setBillsFile]  = useState(null)
  const [orders, setOrders] = useState([])
  const [bills,  setBills]  = useState([])
  const [skus,   setSkus]   = useState([])
  const [summary, setSummary] = useState(null)
  const [busy,  setBusy]  = useState(false)
  const [error, setError] = useState('')
  const [note,  setNote]  = useState('')
  // What the user is currently typing per line. SmartCell filters on its own
  // `value`, so without this the box would always filter against the saved code
  // and show the whole catalogue.
  const [skuDraft, setSkuDraft] = useState({})

  // Bills persist, so show whatever is already stored before any upload.
  useEffect(() => {
    getPurchaseBills().then(setBills).catch(() => {})
    getSkus().then(setSkus).catch(() => {})
  }, [])

  const refresh = () => getPurchaseBills().then(setBills).catch(() => {})

  const run = async () => {
    if (!ordersFile && !billsFile) { setError('Choose an order list, a bill statement, or both.'); return }
    setBusy(true); setError(''); setNote('')
    try {
      const fd = new FormData()
      if (ordersFile) fd.append('orders_csv', ordersFile)
      if (billsFile)  fd.append('bills_pdf',  billsFile)
      const res = await checkBillDiscrepancies(fd)
      setOrders(res.orders || [])
      setSummary(res.summary || null)
      if (res.stored_bills?.length) setBills(res.stored_bills)
      const s = res.saved || {}
      if (s.bills_created || s.bills_updated) {
        setNote(`${s.bills_created} bills added, ${s.bills_updated} updated.`)
      }
    } catch (e) {
      setError(errText(e, 'Could not read those files'))
    } finally {
      setBusy(false)
    }
  }

  const doLink = async (line, sku_id, pack_multiple) => {
    try {
      await linkBillLine(line.id, { sku_id: sku_id || undefined, pack_multiple, remember: true })
      await refresh()
    } catch (e) { setError(errText(e, 'Could not link that line')) }
  }

  const doApply = async (line) => {
    try {
      const r = await applyBillCost(line.id)
      setNote(`${line.item_name.slice(0, 40)} → cost ${money(r.previous_cost)} → ${money(r.new_cost)}`)
      await refresh()
    } catch (e) { setError(errText(e, 'Could not apply that cost')) }
  }

  // One shared option list for every row's search box.
  const skuOpts = useMemo(
    () => skus.map(s => ({ label: s.shringar_sku, sublabel: s.vendor_sku || '' })), [skus])

  const billLines = bills.flatMap(b =>
    (b.lines.length ? b.lines : [null]).map((ln, i) => ({ b, ln, first: i === 0 })))
  const linked   = bills.flatMap(b => b.lines).filter(l => l.sku_id).length
  const totalLn  = bills.flatMap(b => b.lines).length
  const mismatch = bills.flatMap(b => b.lines).filter(l => l.cost_diff != null && l.cost_diff !== 0).length

  return (
    <div className="bd">
      <div className="bd-upload">
        <Upload label="Order list" hint="Flipkart .csv" accept=".csv,text/csv"
          file={ordersFile} onPick={setOrdersFile} />
        <Upload label="Bill statement" hint="Vyapar .pdf" accept=".pdf,application/pdf"
          file={billsFile} onPick={setBillsFile} />
        <button className="bd-run" onClick={run} disabled={busy}>
          {busy ? 'Reading…' : 'Upload & match'}
        </button>
      </div>

      {error && <div className="lg-error" role="alert">{error}</div>}
      {note && <div className="bd-note" role="status">{note}</div>}

      {!bills.length && !orders.length && !error && (
        <p className="bd-hint">
          Upload a supplier bill statement to match its items to your SKUs and
          compare each billed rate against the cost you have recorded.
        </p>
      )}

      {(summary || bills.length > 0) && (
        <div className="lg-stats bd-stats">
          <div className="lg-stat"><span className="lg-stat-l">Bills</span>
            <span className="lg-stat-v">{bills.length}</span>
            <span className="lg-stat-s">{totalLn} lines</span></div>
          <div className="lg-stat"><span className="lg-stat-l">Matched to SKU</span>
            <span className="lg-stat-v">{linked}</span>
            <span className="lg-stat-s">{totalLn - linked} still unmatched</span></div>
          <div className="lg-stat"><span className="lg-stat-l">Cost mismatches</span>
            <span className="lg-stat-v">{mismatch}</span>
            <span className="lg-stat-s">billed rate ≠ recorded cost</span></div>
          <div className="lg-stat"><span className="lg-stat-l">Orders</span>
            <span className="lg-stat-v">{summary?.order_count ?? 0}</span>
            <span className="lg-stat-s">{money(summary?.orders_total)} invoiced</span></div>
        </div>
      )}

      {!!bills.length && (
        <section className="bd-sec">
          <h3 className="bd-h">Bill items vs your SKU cost <small>{bills.length} bills</small></h3>
          <div className="lg-table-wrap">
            <table className="lg-table bd-table">
              <thead>
                <tr>
                  <th>Date</th><th>Ref</th><th>Item</th>
                  <th className="num">Rate</th><th className="num">Pack</th><th className="num">Unit cost</th>
                  <th>Matched SKU</th><th className="num">Recorded</th><th className="num">Diff</th><th></th>
                </tr>
              </thead>
              <tbody>
                {billLines.map(({ b, ln, first }, i) => (
                  <tr key={ln ? ln.id : `${b.id}-x`} className={first ? 'bd-first' : undefined}>
                    <td className="mono nowrap">{first ? b.bill_date : ''}</td>
                    <td className="mono">{first ? b.ref_no : ''}</td>
                    <td className="bd-prod">{ln ? ln.item_name : <em>no line items</em>}</td>
                    <td className="num mono">{ln ? money(ln.price_unit) : ''}</td>
                    <td className="num">
                      {ln && (
                        <input className="bd-pack" type="number" min="1" step="1"
                          defaultValue={ln.pack_multiple}
                          title="How many SKU units one billed unit contains"
                          onBlur={e => {
                            const v = parseFloat(e.target.value) || 1
                            if (v !== ln.pack_multiple) doLink(ln, ln.sku_id, v)
                          }} />
                      )}
                    </td>
                    <td className="num mono">{ln ? money(ln.unit_cost) : ''}</td>
                    <td className="bd-skucell">
                      {ln && (
                        /* Type-to-search, not a dropdown — a catalogue can run to
                           thousands of SKUs, and there is one of these per line. */
                        <SmartCell
                          value={skuDraft[ln.id] ?? ln.sku_code ?? ''}
                          options={skuOpts}
                          placeholder="search SKU…"
                          onChange={v => {
                            setSkuDraft(d => ({ ...d, [ln.id]: v }))
                            if (!v && ln.sku_id) doLink(ln, null, ln.pack_multiple)
                          }}
                          onSelect={opt => {
                            const hit = skus.find(s => s.shringar_sku === opt.label)
                            setSkuDraft(d => { const n = { ...d }; delete n[ln.id]; return n })
                            if (hit) doLink(ln, hit.id, ln.pack_multiple)
                          }}
                        />
                      )}
                      {ln?.match_source === 'suggested' && <Flag>suggested</Flag>}
                      {ln?.match_source === 'alias' && <Flag tone="ok">remembered</Flag>}
                    </td>
                    <td className="num mono">{ln ? money(ln.recorded_cost) : ''}</td>
                    <td className="num mono">
                      {ln && ln.cost_diff != null && (
                        ln.cost_diff === 0
                          ? <Flag tone="ok">match</Flag>
                          : <Flag tone="bad">{ln.cost_diff > 0 ? '+' : ''}{money(ln.cost_diff)}</Flag>
                      )}
                    </td>
                    <td>
                      {ln?.sku_id && ln.cost_diff !== 0 && (
                        <button className="bd-apply" onClick={() => doApply(ln)}
                          title="Set this SKU's Product Cost to the unit cost above">
                          Apply cost
                        </button>
                      )}
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
          <p className="bd-foot">
            <strong>Pack</strong> is how many SKU units one billed unit contains — a ₹90 box of 6
            is ₹15 a glass. Set it before trusting the difference. Matches you pick are
            remembered for this supplier, so the next statement resolves them itself.
          </p>
        </section>
      )}

      {!!orders.length && (
        <section className="bd-sec">
          <h3 className="bd-h">Order list <small>{orders.length} orders · {money(summary?.orders_total)}</small></h3>
          <div className="lg-table-wrap">
            <table className="lg-table bd-table">
              <thead>
                <tr><th>Date</th><th>SKU</th><th>Product</th><th>Invoice no.</th>
                  <th className="num">Qty</th><th className="num">Amount</th><th>Status</th><th>Flag</th></tr>
              </thead>
              <tbody>
                {orders.map(o => (
                  <tr key={o.order_id}>
                    <td className="mono nowrap">{o.ordered_on}</td>
                    <td className="mono">{o.sku || '—'}</td>
                    <td className="bd-prod" title={o.product}>{o.product}</td>
                    <td className="mono">{o.invoice_no || '—'}</td>
                    <td className="num mono">{o.quantity}</td>
                    <td className="num mono">{money(o.invoice_amount)}</td>
                    <td className="nowrap">{o.state}</td>
                    <td>
                      {!o.sku_known && <Flag>not in catalogue</Flag>}
                      {/return/i.test(o.state || '') && <Flag tone="bad">returned</Flag>}
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        </section>
      )}
    </div>
  )
}

import { useEffect, useRef, useState } from 'react'
import './ConfirmDialog.css'

/**
 * In-app confirmation.
 *
 * Replaces window.confirm, which renders the browser's own "localhost:5173 says"
 * box — unstyled, unbranded, and unable to show anything but plain text. Same
 * reason the company-create prompt was replaced earlier.
 *
 * Controlled, not promise-based: the caller keeps the pending action in state and
 * runs it in onConfirm, so the flow stays visible in the component that owns it.
 */
export default function ConfirmDialog({
  open, title, children, confirmLabel = 'Confirm', cancelLabel = 'Cancel',
  tone = 'default',            // 'default' | 'danger'
  onConfirm, onCancel,
}) {
  const confirmRef = useRef(null)

  useEffect(() => {
    if (!open) return
    confirmRef.current?.focus()
    const onKey = e => {
      if (e.key === 'Escape') onCancel?.()
      if (e.key === 'Enter')  onConfirm?.()
    }
    document.addEventListener('keydown', onKey)
    return () => document.removeEventListener('keydown', onKey)
  }, [open, onConfirm, onCancel])

  if (!open) return null

  return (
    <div className="cd-overlay" onClick={onCancel} role="presentation">
      <div className="cd-box" role="alertdialog" aria-modal="true" aria-label={title}
        onClick={e => e.stopPropagation()}>
        <div className="cd-title">{title}</div>
        <div className="cd-body">{children}</div>
        <div className="cd-actions">
          <button className="cd-btn cd-cancel" onClick={onCancel}>{cancelLabel}</button>
          <button ref={confirmRef} className={`cd-btn cd-confirm${tone === 'danger' ? ' danger' : ''}`}
            onClick={onConfirm}>{confirmLabel}</button>
        </div>
      </div>
    </div>
  )
}

/**
 * Convenience wrapper so a call site is two lines instead of its own state block.
 *
 *   const { ask, dialog } = useConfirm()
 *   ...
 *   <button onClick={() => ask({
 *     title: 'Delete invoice',
 *     body: <>Delete <strong>{inv.number}</strong>? This cannot be undone.</>,
 *     confirmLabel: 'Delete', tone: 'danger',
 *     onConfirm: () => remove(inv),
 *   })}>Delete</button>
 *   ...
 *   {dialog}
 *
 * The action runs after the dialog closes, so an async handler cannot leave the
 * dialog open behind a request.
 */
export function useConfirm() {
  const [pending, setPending] = useState(null)

  const dialog = (
    <ConfirmDialog
      open={!!pending}
      title={pending?.title}
      confirmLabel={pending?.confirmLabel}
      cancelLabel={pending?.cancelLabel}
      tone={pending?.tone}
      onCancel={() => setPending(null)}
      onConfirm={() => { const p = pending; setPending(null); p?.onConfirm?.() }}
    >
      {pending?.body}
    </ConfirmDialog>
  )

  return { ask: setPending, dialog }
}

import { useState } from 'react'
import './IntroPage.css'

/**
 * IntroPage — reusable in-app help/intro template.
 *
 * Structure (per section):
 *   1. WHAT — plain English, what this feature does
 *   2. MATH — formulas with worked example using realistic numbers
 *   3. TECHNICAL — collapsible details (file paths, API endpoints, edge cases)
 *
 * Usage:
 *   <IntroPage title="Profit & Loss" emoji="💰" tagline="...">
 *     <IntroSection title="What this does"> ... </IntroSection>
 *     <MathSection formula="..." explanation="..." example={{...}} />
 *     <TechSection items={[...]} />
 *   </IntroPage>
 */
export default function IntroPage({ title, emoji = '📖', tagline, children }) {
  return (
    <div className="intro-page">
      <div className="intro-header">
        {emoji && <span className="intro-emoji">{emoji}</span>}
        <div>
          <h1 className="intro-title">{title}</h1>
          {tagline && <p className="intro-tagline">{tagline}</p>}
        </div>
      </div>
      <div className="intro-body">
        {children}
      </div>
    </div>
  )
}

/** Plain-language section. */
export function IntroSection({ title, children }) {
  return (
    <section className="intro-section">
      <h2 className="intro-section-title">{title}</h2>
      <div className="intro-section-body">{children}</div>
    </section>
  )
}

/**
 * Math section — formula on top, explanation, worked example below.
 *
 * Props:
 *   title           — defaults to "The Math"
 *   formula         — single-line formula string (rendered in monospace)
 *   explanation     — JSX/string explaining in plain English
 *   example         — { title, inputs: [{label, value}], output: {label, value, valueClass}, breakdown?: string }
 *   variants        — optional array of { title, formula, explanation, example } for multi-formula sections
 */
export function MathSection({ title = 'The Math', formula, explanation, example, variants }) {
  return (
    <section className="intro-section intro-math-section">
      <h2 className="intro-section-title">{title}</h2>
      <div className="intro-section-body">
        {formula && <pre className="intro-formula">{formula}</pre>}
        {explanation && <div className="intro-explanation">{explanation}</div>}
        {example && <ExampleBlock {...example} />}
        {variants && variants.map((v, i) => (
          <div key={i} className="intro-variant">
            <h3 className="intro-variant-title">{v.title}</h3>
            {v.formula && <pre className="intro-formula">{v.formula}</pre>}
            {v.explanation && <div className="intro-explanation">{v.explanation}</div>}
            {v.example && <ExampleBlock {...v.example} />}
          </div>
        ))}
      </div>
    </section>
  )
}

function ExampleBlock({ title = 'Example', inputs = [], output, breakdown }) {
  return (
    <div className="intro-example">
      <div className="intro-example-title">{title}</div>
      <div className="intro-example-grid">
        {inputs.map((inp, i) => (
          <div key={i} className="intro-example-row">
            <span className="intro-example-label">{inp.label}</span>
            <span className="intro-example-value">{inp.value}</span>
          </div>
        ))}
        {breakdown && (
          <div className="intro-example-breakdown">{breakdown}</div>
        )}
        {output && (
          <div className="intro-example-row intro-example-output">
            <span className="intro-example-label"><strong>{output.label}</strong></span>
            <span className={`intro-example-value strong ${output.valueClass || ''}`}>{output.value}</span>
          </div>
        )}
      </div>
    </div>
  )
}

/**
 * Technical section — collapsible accordion with key-value pairs.
 * Hidden by default so user-facing content stays clean.
 *
 * Props:
 *   items: [{ label, value, code? }]   — `code: true` renders the value as monospace
 */
export function TechSection({ items = [], title = 'Technical details (for developers)' }) {
  const [open, setOpen] = useState(false)
  return (
    <section className="intro-section intro-tech-section">
      <button className="intro-tech-toggle" onClick={() => setOpen(o => !o)}>
        <span className="intro-tech-chev">{open ? '▾' : '▸'}</span>
        {title}
      </button>
      {open && (
        <div className="intro-tech-body">
          {items.map((it, i) => (
            <div key={i} className="intro-tech-row">
              <span className="intro-tech-label">{it.label}</span>
              <span className={`intro-tech-value ${it.code ? 'mono' : ''}`}>{it.value}</span>
            </div>
          ))}
        </div>
      )}
    </section>
  )
}

/**
 * Tip / callout block.
 * variant: 'info' | 'warn' | 'success'
 */
export function Callout({ variant = 'info', children }) {
  const icon = variant === 'warn' ? '⚠️' : variant === 'success' ? '✓' : 'ℹ️'
  return (
    <div className={`intro-callout intro-callout-${variant}`}>
      <span className="intro-callout-icon">{icon}</span>
      <div>{children}</div>
    </div>
  )
}

