import { useState } from 'react'
import './ManageCategoriesModal.css'

/**
 * ManageCategoriesModal
 * ──────────────────────────────────────────────────────────────────────
 * Each row shows: name + per-category defaults (CR%, Damage%, Profit%).
 * Defaults cascade to new SKUs in the category; per-SKU override still works.
 * Edit mode toggles inputs inline; Save commits via onUpdate(id, patch).
 */
export default function ManageCategoriesModal({ categories, rows, onClose, onUpdate, onDelete }) {
  const [editId,   setEditId]   = useState(null)
  const [draft,    setDraft]    = useState({})    // { name, default_cr_pct, default_damage_pct, default_profit_pct }
  const [busy,     setBusy]     = useState(null)

  const skuCount = cat =>
    rows.filter(r => r.categoryId === cat.id || r.category === cat.name).length

  const numOrNull = v => {
    if (v === '' || v === null || v === undefined) return null
    const n = parseFloat(v)
    return Number.isFinite(n) ? n : null
  }

  const startEdit = cat => {
    setEditId(cat.id)
    setDraft({
      name:                 cat.name,
      default_cr_pct:       cat.default_cr_pct ?? '',
      default_damage_pct:   cat.default_damage_pct ?? '',
      default_profit_pct:   cat.default_profit_pct ?? '',
    })
  }
  const cancelEdit = () => { setEditId(null); setDraft({}) }

  const saveEdit = async cat => {
    if (!draft.name?.trim()) return cancelEdit()
    setBusy(cat.id)
    try {
      await onUpdate(cat.id, {
        name:                 draft.name.trim(),
        default_cr_pct:       numOrNull(draft.default_cr_pct),
        default_damage_pct:   numOrNull(draft.default_damage_pct),
        default_profit_pct:   numOrNull(draft.default_profit_pct),
      })
    } finally { setBusy(null); cancelEdit() }
  }

  const handleDelete = async cat => {
    if (skuCount(cat) > 0) return
    setBusy(cat.id)
    try { await onDelete(cat.id) } finally { setBusy(null) }
  }

  return (
    <div className="mc-backdrop" onClick={e => e.target === e.currentTarget && onClose()}>
      <div className="mc-modal" style={{ width: 520 }}>
        <div className="mc-hdr">
          <span>Manage Categories</span>
          <button className="mc-close" onClick={onClose}>✕</button>
        </div>
        <div className="mc-body">
          {categories.length === 0 && (
            <div className="mc-empty">No categories yet.</div>
          )}
          {/* Column hints */}
          {categories.length > 0 && (
            <div className="mc-hints">
              <span style={{ flex: 1 }}>Name</span>
              <span className="mc-hint-pct">CR %</span>
              <span className="mc-hint-pct">Dmg %</span>
              <span className="mc-hint-pct">Profit %</span>
              <span style={{ width: 90 }} />
            </div>
          )}
          {categories.map(cat => {
            const count  = skuCount(cat)
            const isEdit = editId === cat.id
            const isBusy = busy === cat.id
            return (
              <div key={cat.id} className="mc-row">
                {isEdit ? (
                  <>
                    <input
                      className="mc-input"
                      value={draft.name}
                      autoFocus
                      onChange={e => setDraft(d => ({ ...d, name: e.target.value }))}
                      onKeyDown={e => {
                        if (e.key === 'Enter')  saveEdit(cat)
                        if (e.key === 'Escape') cancelEdit()
                      }}
                    />
                    <input className="mc-pct-inp" type="number"
                      value={draft.default_cr_pct}
                      onChange={e => setDraft(d => ({ ...d, default_cr_pct: e.target.value }))} />
                    <input className="mc-pct-inp" type="number"
                      value={draft.default_damage_pct}
                      onChange={e => setDraft(d => ({ ...d, default_damage_pct: e.target.value }))} />
                    <input className="mc-pct-inp" type="number"
                      value={draft.default_profit_pct}
                      onChange={e => setDraft(d => ({ ...d, default_profit_pct: e.target.value }))} />
                  </>
                ) : (
                  <>
                    <span className="mc-name">{cat.name}</span>
                    <span className="mc-pct-show">{cat.default_cr_pct ?? '—'}</span>
                    <span className="mc-pct-show">{cat.default_damage_pct ?? '—'}</span>
                    <span className="mc-pct-show">{cat.default_profit_pct ?? '—'}</span>
                  </>
                )}
                <div className="mc-actions">
                  <span className={`mc-badge ${count > 0 ? 'mc-badge-used' : 'mc-badge-free'}`}>
                    {count > 0 ? `${count}` : '—'}
                  </span>
                  {isEdit ? (
                    <>
                      <button className="mc-btn mc-save" onClick={() => saveEdit(cat)} disabled={isBusy}>
                        {isBusy ? '…' : '✓'}
                      </button>
                      <button className="mc-btn mc-cancel" onClick={cancelEdit}>✕</button>
                    </>
                  ) : (
                    <>
                      <button className="mc-btn mc-edit" onClick={() => startEdit(cat)} disabled={isBusy} title="Edit">✎</button>
                      <button
                        className="mc-btn mc-del"
                        onClick={() => handleDelete(cat)}
                        disabled={count > 0 || isBusy}
                        title={count > 0 ? 'In use — cannot delete' : 'Delete'}
                      >{isBusy ? '…' : '✕'}</button>
                    </>
                  )}
                </div>
              </div>
            )
          })}
        </div>
      </div>
    </div>
  )
}

import { useState, useRef, useEffect } from 'react'
import './SmartCell.css'

/**
 * SmartCell — Excel-style autocomplete input
 * 
 * Props:
 * - value: current value string
 * - options: array of { label, sublabel? } to suggest
 * - placeholder: input placeholder
 * - onChange: called when value changes (typing)
 * - onSelect: called when user picks an option { label, sublabel }
 * - onAddNew: called when user wants to add a new item (label string)
 * - addNewLabel: text for the "add new" option e.g. "Add as new vendor"
 * - readOnly: disable editing
 */
export default function SmartCell({
  value = '',
  options = [],
  placeholder = '',
  onChange,
  onSelect,
  onAddNew,
  addNewLabel = 'Add as new item',
  onManage,
  readOnly = false,
  className = '',
}) {
  const [open, setOpen]         = useState(false)
  const [activeIdx, setActiveIdx] = useState(0)
  const inputRef = useRef()
  const ddRef    = useRef()
  const cellRef  = useRef()

  // Filter options based on current value
  const filtered = options.filter(opt =>
    opt.label.toLowerCase().includes(value.toLowerCase()) ||
    (opt.sublabel || '').toLowerCase().includes(value.toLowerCase())
  )

  // Check if exact match exists
  const exactMatch = options.find(
    opt => opt.label.toLowerCase() === value.toLowerCase()
  )

  // Show "Add new" only if user typed something and no exact match
  const showAddNew = onAddNew && value.trim().length > 0 && !exactMatch

  const totalItems = filtered.length + (showAddNew ? 1 : 0)

  // Close dropdown when clicking outside
  useEffect(() => {
    const handler = (e) => {
      if (cellRef.current && !cellRef.current.contains(e.target)) {
        setOpen(false)
      }
    }
    document.addEventListener('mousedown', handler)
    return () => document.removeEventListener('mousedown', handler)
  }, [])

  // Reset active index when options change
  useEffect(() => { setActiveIdx(0) }, [value])

  const handleKeyDown = (e) => {
    if (!open) {
      if (e.key === 'ArrowDown') { setOpen(true); return }
      return
    }

    if (e.key === 'ArrowDown') {
      e.preventDefault()
      setActiveIdx(i => Math.min(i + 1, totalItems - 1))
    } else if (e.key === 'ArrowUp') {
      e.preventDefault()
      setActiveIdx(i => Math.max(i - 1, 0))
    } else if (e.key === 'Enter' || e.key === 'Tab') {
      e.preventDefault()
      if (activeIdx < filtered.length) {
        handleSelect(filtered[activeIdx])
      } else if (showAddNew) {
        onAddNew(value.trim())
        setOpen(false)
      }
    } else if (e.key === 'Escape') {
      setOpen(false)
    }
  }

  const handleSelect = (opt) => {
    onSelect && onSelect(opt)
    setOpen(false)
    inputRef.current?.blur()
  }

  // Highlight matching part of text in bold
  const highlight = (text, query) => {
    if (!query) return text
    const idx = text.toLowerCase().indexOf(query.toLowerCase())
    if (idx === -1) return text
    return (
      <>
        {text.slice(0, idx)}
        <strong>{text.slice(idx, idx + query.length)}</strong>
        {text.slice(idx + query.length)}
      </>
    )
  }

  return (
    <div ref={cellRef} className={`sc-wrap ${className}`}>
      <span className="ec-sizer">{value || placeholder}</span>
      <input
        ref={inputRef}
        className="sc-input"
        value={value}
        placeholder={placeholder}
        readOnly={readOnly}
        size={1}
        onChange={e => {
          onChange && onChange(e.target.value)
          setOpen(true)
        }}
        onFocus={() => setOpen(true)}
        onKeyDown={handleKeyDown}
      />

      {open && totalItems > 0 && (
        <div ref={ddRef} className="sc-dropdown">

          {/* Hint */}
          {filtered.length > 0 && (
            <div className="sc-hint">
              ↑↓ navigate · Enter/Tab to select · Esc to close
            </div>
          )}

          {/* Options list */}
          {filtered.map((opt, i) => (
            <div
              key={i}
              className={`sc-option ${i === activeIdx ? 'sc-active' : ''}`}
              onMouseEnter={() => setActiveIdx(i)}
              onMouseDown={() => handleSelect(opt)}
            >
              <span className="sc-option-label">
                {highlight(opt.label, value)}
              </span>
              {opt.sublabel && (
                <span className="sc-option-sub">{opt.sublabel}</span>
              )}
            </div>
          ))}

          {/* Add new option */}
          {showAddNew && (
            <div
              className={`sc-addnew ${activeIdx === filtered.length ? 'sc-active' : ''}`}
              onMouseEnter={() => setActiveIdx(filtered.length)}
              onMouseDown={() => { onAddNew(value.trim()); setOpen(false) }}
            >
              <span className="sc-plus">+</span>
              {addNewLabel} "{value.trim()}"
            </div>
          )}
          {/* Manage link */}
          {onManage && (
            <div className="sc-manage" onMouseDown={() => { onManage(); setOpen(false) }}>
              ⚙ Manage categories →
            </div>
          )}
        </div>
      )}
    </div>
  )
}

import { useState } from 'react'
// xlsx is lazy-loaded inside the file handler (keeps it out of the main bundle).

/**
 * UploadAdReportModal
 * ──────────────────────────────────────────────────────────────────────
 * Upload a platform ad-campaign report (CSV / XLSX) and apply per-SKU
 * AD ₹/unit to the SKUs page rows.
 *
 * Expected columns (case-insensitive):
 *   • SKU        — matches Casper sku_name OR platform_sku_name (alias)
 *   • Spend      — total ad spend in ₹
 *   • Orders     — total orders attributed to that ad
 *
 * Computed:  ad_amt_per_unit = Spend / Orders
 *
 * Matching priority for each report row:
 *   1. exact match on Casper sku_name (case-insensitive)
 *   2. exact match on row.platAliases[platform.id] (case-insensitive)
 *   3. unmatched → shown in preview, skipped on apply
 *
 * Props:
 *   platform   — { id, name, … }
 *   rows       — current SKU rows (for matching)
 *   onApply    — (updates: [{ rowId, adAmt }]) => void   parent merges into platOverrides
 *   onClose    — () => void
 */
export default function UploadAdReportModal({ platform, rows, onApply, onClose }) {
  const [file,        setFile]        = useState(null)
  const [parsing,     setParsing]     = useState(false)
  const [parseError,  setParseError]  = useState('')
  const [matched,     setMatched]     = useState([])  // [{ rowId, sku, adAmt, spend, orders }]
  const [unmatched,   setUnmatched]   = useState([])  // [{ sku, spend, orders, reason }]

  const norm = s => String(s ?? '').trim().toLowerCase()

  const handleFile = e => {
    const f = e.target.files?.[0]
    if (!f) return
    setFile(f)
    setParseError('')
    setParsing(true)

    const reader = new FileReader()
    reader.onload = async ev => {
      try {
        const XLSX = await import('xlsx')
        const wb = XLSX.read(ev.target.result, { type: 'array' })
        const ws = wb.Sheets[wb.SheetNames[0]]
        const raw = XLSX.utils.sheet_to_json(ws, { defval: '' })

        // Find columns case-insensitively
        const findKey = (row, ...names) => {
          const keys = Object.keys(row)
          for (const n of names) {
            const k = keys.find(k => k.trim().toLowerCase() === n.toLowerCase())
            if (k) return k
          }
          return null
        }

        if (raw.length === 0) { setParseError('File is empty.'); setParsing(false); return }
        const sample = raw[0]
        const skuKey    = findKey(sample, 'SKU', 'SKU Name', 'Product')
        const spendKey  = findKey(sample, 'Spend', 'Total Spend', 'Amount Spent', 'Cost')
        const ordersKey = findKey(sample, 'Orders', 'Total Orders', 'Conversions')

        if (!skuKey || !spendKey || !ordersKey) {
          setParseError(`Missing columns. Need: SKU, Spend, Orders. Found: ${Object.keys(sample).join(', ')}`)
          setParsing(false)
          return
        }

        const M = []  // matched
        const U = []  // unmatched

        raw.forEach(r => {
          const sku    = String(r[skuKey] ?? '').trim()
          const spend  = parseFloat(r[spendKey])
          const orders = parseFloat(r[ordersKey])
          if (!sku) return
          if (!Number.isFinite(spend) || !Number.isFinite(orders) || orders <= 0) {
            U.push({ sku, spend, orders, reason: 'invalid spend/orders' })
            return
          }
          const adAmt = +(spend / orders).toFixed(2)

          // Try direct sku_name match
          const skuLower = norm(sku)
          let row = rows.find(rr => norm(rr.sku) === skuLower)
          // Fallback: alias match
          if (!row) {
            row = rows.find(rr => {
              const alias = rr.platAliases?.[platform.id]
              return alias && norm(alias) === skuLower
            })
          }

          if (row) {
            M.push({ rowId: row.id, sku: row.sku, adAmt, spend, orders })
          } else {
            U.push({ sku, spend, orders, reason: 'no matching SKU' })
          }
        })

        setMatched(M)
        setUnmatched(U)
      } catch (err) {
        setParseError(err?.message || 'Failed to parse file')
      } finally {
        setParsing(false)
      }
    }
    reader.readAsArrayBuffer(f)
  }

  const apply = () => {
    if (matched.length === 0) return
    onApply(matched.map(m => ({ rowId: m.rowId, adAmt: m.adAmt })))
  }

  return (
    <div className="overlay" onClick={e => e.target === e.currentTarget && onClose()}>
      <div className="modal" style={{ maxWidth: 640, maxHeight: '80vh', display: 'flex', flexDirection: 'column' }}>
        <div className="modal-title">Upload Ad Report · {platform.name}</div>

        <div style={{ fontSize: 12, color: 'var(--text-3)', marginBottom: 10 }}>
          File should have columns: <strong>SKU</strong>, <strong>Spend</strong>, <strong>Orders</strong>.
          Per-SKU AD ₹/unit = Spend ÷ Orders.
        </div>

        <input type="file" accept=".csv,.xlsx,.xls" onChange={handleFile}
          style={{ marginBottom: 10 }} />

        {parsing && <div style={{ fontSize: 12 }}>Parsing…</div>}
        {parseError && (
          <div style={{
            padding: '8px 12px', background: 'var(--red-dim)',
            border: '1px solid var(--red)', borderRadius: 'var(--radius-sm)',
            color: 'var(--red)', fontSize: 12, marginBottom: 10,
          }}>{parseError}</div>
        )}

        {(matched.length > 0 || unmatched.length > 0) && (
          <div style={{ display: 'flex', gap: 8, marginBottom: 10, fontSize: 12 }}>
            <span style={{ padding: '4px 10px', background: '#ecfdf5', color: '#059669', borderRadius: 6, fontWeight: 600 }}>
              {matched.length} matched
            </span>
            {unmatched.length > 0 && (
              <span style={{ padding: '4px 10px', background: '#fef3c7', color: '#a16207', borderRadius: 6, fontWeight: 600 }}>
                {unmatched.length} unmatched
              </span>
            )}
          </div>
        )}

        <div style={{ flex: 1, overflowY: 'auto', minHeight: 0 }}>
          {matched.length > 0 && (
            <table style={{ width: '100%', fontSize: 12, borderCollapse: 'collapse' }}>
              <thead>
                <tr style={{ background: 'var(--surface-2)' }}>
                  <th style={{ textAlign: 'left',  padding: '6px 8px' }}>SKU</th>
                  <th style={{ textAlign: 'right', padding: '6px 8px' }}>Spend ₹</th>
                  <th style={{ textAlign: 'right', padding: '6px 8px' }}>Orders</th>
                  <th style={{ textAlign: 'right', padding: '6px 8px', color: '#059669' }}>AD ₹/unit</th>
                </tr>
              </thead>
              <tbody>
                {matched.slice(0, 100).map((m, i) => (
                  <tr key={i} style={{ borderTop: '1px solid var(--border)' }}>
                    <td style={{ padding: '4px 8px' }}>{m.sku}</td>
                    <td style={{ padding: '4px 8px', textAlign: 'right', fontFamily: 'var(--font-mono)' }}>{m.spend.toFixed(0)}</td>
                    <td style={{ padding: '4px 8px', textAlign: 'right', fontFamily: 'var(--font-mono)' }}>{m.orders.toFixed(0)}</td>
                    <td style={{ padding: '4px 8px', textAlign: 'right', fontFamily: 'var(--font-mono)', color: '#059669', fontWeight: 600 }}>{m.adAmt}</td>
                  </tr>
                ))}
                {matched.length > 100 && (
                  <tr><td colSpan="4" style={{ padding: 8, color: 'var(--text-3)', fontSize: 11 }}>
                    + {matched.length - 100} more rows…
                  </td></tr>
                )}
              </tbody>
            </table>
          )}
          {unmatched.length > 0 && (
            <div style={{ marginTop: 12 }}>
              <div style={{ fontSize: 11, fontWeight: 600, color: 'var(--text-2)', marginBottom: 4, textTransform: 'uppercase', letterSpacing: 0.4 }}>
                Skipped rows
              </div>
              <table style={{ width: '100%', fontSize: 11, borderCollapse: 'collapse' }}>
                <tbody>
                  {unmatched.slice(0, 50).map((u, i) => (
                    <tr key={i} style={{ borderTop: '1px solid var(--border)' }}>
                      <td style={{ padding: '4px 8px' }}>{u.sku}</td>
                      <td style={{ padding: '4px 8px', color: 'var(--text-3)' }}>{u.reason}</td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          )}
        </div>

        <div className="form-actions" style={{ marginTop: 12 }}>
          <button className="btn btn-ghost" onClick={onClose}>Cancel</button>
          <button className="btn btn-gold" onClick={apply}
            disabled={matched.length === 0 || parsing}>
            Apply to {matched.length} SKU{matched.length === 1 ? '' : 's'}
          </button>
        </div>
      </div>
    </div>
  )
}

