// ── Chart tooltip ─────────────────────────────────────────────────────────
const WEEK_MON = { W1:'Mar',W2:'Mar',W3:'Apr',W4:'Apr',W5:'May',W6:'May',W7:'Jun',W8:'Jun',W9:'Jul',W10:'Jul',W11:'Aug',W12:'Aug' }
function ChartTooltip({ active, payload, label }) {
