                  <td className="fd-td fd-num">{pct(r.rto_rate)}</td>
                  <td className="fd-td fd-num">{r.z_score != null ? r.z_score.toFixed(2) : '—'}</td>
                  <td className="fd-td fd-num" style={{ fontWeight: 700 }}>
                    <span style={{ color: (r.composite_fraud_score || 0) >= 50 ? '#ef4444' : (r.composite_fraud_score || 0) >= 30 ? '#f59e0b' : '#22c55e' }}>
                      {r.composite_fraud_score != null ? r.composite_fraud_score.toFixed(0) : '—'}
                    </span>
                  </td>
                  <td className="fd-td">
                    <span className="fd-badge" style={{ color: tier.color, background: tier.bg }}>
                      {r.risk_tier}
                    </span>
                  </td>
                </tr>
              )
            })}
          </tbody>
        </table>
      </div>
    </div>
  )
}

