// Shows return velocity intelligence for SKUs on a given platform.
// Includes honest data-unlock notice when velocity data is unavailable.

export default function VelocityPanel({ skus, platform }) {
  const withVelocity = (skus || []).filter(s => s.avg_return_velocity_days != null)

  if (!withVelocity.length) {
    const msg = platform?.toLowerCase().includes('flipkart')
      ? 'Flipkart P&L exports do not include delivery or return-pickup dates. Upload a Shipment Report to unlock velocity intelligence.'
      : platform?.toLowerCase().includes('meesho')
      ? 'Meesho dispatch/payment dates parsed but return-pickup date not available — cannot compute true delivery→return velocity.'
      : 'No delivery→return-pickup date pairs found in this report. Velocity intelligence requires Snapdeal CPR format with del_date + RPU_date columns.'

    return (
      <div className="vel-empty">
        <div className="vel-lock-icon">🔒</div>
        <div className="vel-lock-title">Velocity Data Unavailable</div>
        <div className="vel-lock-body">{msg}</div>
      </div>
    )
  }

  const fraudSkus = withVelocity
    .filter(s => s.velocity_fraud_count > 0)
    .sort((a, b) => b.velocity_fraud_count - a.velocity_fraud_count)

  return (
    <div className="vel-root">
      <div className="vel-summary">
        <span className="vel-stat-val">{fraudSkus.length}</span>
        <span className="vel-stat-lbl">SKUs with rapid returns (≤3 days)</span>
      </div>

      {fraudSkus.length === 0 && (
        <div className="vel-clean">
          ✅ No rapid-return patterns across {withVelocity.length} tracked SKUs
        </div>
      )}

      {fraudSkus.map((s, i) => (
        <div key={i} className="vel-row">
          <div className="vel-sku-name">{s.sku_platform_name}</div>
          <div className="vel-bars">
            <div className="vel-bar-row">
              <span className="vel-bar-label">Avg velocity</span>
              <span className={`vel-bar-val ${s.avg_return_velocity_days <= 3 ? 'warn' : ''}`}>
                {s.avg_return_velocity_days?.toFixed(1)}d
              </span>
            </div>
            <div className="vel-bar-row">
              <span className="vel-bar-label">Rapid returns</span>
              <span className="vel-bar-val warn">{s.velocity_fraud_count}</span>
            </div>
          </div>
        </div>
      ))}
    </div>
  )
}

import { useState, useEffect, useCallback, useMemo } from 'react'
import {
  PieChart, Pie, Cell, BarChart, Bar, XAxis, YAxis, Tooltip, ResponsiveContainer, Legend,
} from 'recharts'
import { useConfirm } from '../components/ConfirmDialog'
import BillDiscrepancies from '../components/BillDiscrepancies'
import {
  getLedger, getLedgerSummary, createLedgerEntry, updateLedgerEntry, deleteLedgerEntry,
  getVendors, getSkus, inCompany, errText,
} from '../api/client'
import { useCompany } from '../context/CompanyContext'
import './Ledger.css'

const EXPENSE_CATS = ['inventory', 'logistics', 'packaging', 'ads', 'salary', 'rent', 'utilities', 'tax', 'platform_fee', 'refund', 'misc']
const INCOME_CATS  = ['settlement', 'sale', 'refund_received', 'other_income']
const METHODS      = ['bank_transfer', 'upi', 'cash', 'card', 'cheque', 'other']
const CHART_COLORS = ['#EC2D6E', '#7A5BFF', '#D97706', '#1FA968', '#2874F0', '#F23A77', '#0EA5E9', '#DB2777', '#65A30D', '#9333EA', '#E11D48']

const today = () => new Date().toISOString().slice(0, 10)
const monthKey = d => (d || '').slice(0, 7)
const blank = () => ({
  entry_date: today(), direction: 'expense', category: 'inventory', amount: '',
  vendor_id: '', party_name: '', sku_id: '', bank_name: '', payment_method: 'bank_transfer',
  reference_no: '', note: '',
})
const fmt   = n => `₹${Number(n || 0).toLocaleString('en-IN', { maximumFractionDigits: 0 })}`
const fmtP  = n => `₹${Number(n || 0).toLocaleString('en-IN', { minimumFractionDigits: 2, maximumFractionDigits: 2 })}`
const label = s => (s || '').replace(/_/g, ' ')

function StatCard({ label, value, tone, sub, icon }) {
  return (
    <div className={`lg-stat lg-stat-${tone}`}>
      <div className="lg-stat-top">
        <span className="lg-stat-ic">{icon}</span>
        <span className="lg-stat-lbl">{label}</span>
      </div>
      <div className="lg-stat-val">{value}</div>
      {sub && <div className="lg-stat-sub">{sub}</div>}
    </div>
  )
}

export default function Ledger() {
  const { ask, dialog } = useConfirm()
  // A new record has no company to infer, so in All Companies the form has to ask.
  // Editing does not: the existing row already carries its own company.
  const { companies, isAll } = useCompany()
  const [newIn, setNewIn]     = useState('')
  const [entries, setEntries] = useState([])
  const [summary, setSummary] = useState({ total_income: 0, total_expense: 0, net: 0, count: 0, by_category: [] })
  const [vendors, setVendors] = useState([])
  const [skus, setSkus]       = useState([])
  const [loading, setLoading] = useState(true)
  const [filter, setFilter]   = useState({ start: '', end: '', direction: '' })
  const [tab, setTab]         = useState('overview')  // overview | entries
  const [showForm, setShowForm] = useState(false)
  const [editId, setEditId]   = useState(null)
  const [draft, setDraft]     = useState(blank())
  const [busy, setBusy]       = useState(false)
  const [error, setError]     = useState('')

  const load = useCallback(async () => {
    setLoading(true)
    const params = {}
    if (filter.start) params.start = filter.start
    if (filter.end) params.end = filter.end
    if (filter.direction) params.direction = filter.direction
    try {
      const [e, s] = await Promise.all([getLedger(params), getLedgerSummary(params)])
      setEntries(e); setSummary(s)
    } catch (err) { setError(errText(err, 'Failed to load ledger')) }
    finally { setLoading(false) }
  }, [filter])

  useEffect(() => { load() }, [load])
  useEffect(() => { getVendors().then(setVendors).catch(() => {}); getSkus().then(setSkus).catch(() => {}) }, [])

  // ── Report aggregations (client-side, from loaded entries) ──────────────────
  const expenseByCat = useMemo(() =>
    (summary.by_category || []).filter(b => b.direction === 'expense')
      .map((b, i) => ({ name: label(b.category), value: b.total, color: CHART_COLORS[i % CHART_COLORS.length] })),
    [summary])

  const monthly = useMemo(() => {
    const m = {}
    for (const e of entries) {
      const k = monthKey(e.entry_date)
      if (!m[k]) m[k] = { month: k, expense: 0, income: 0 }
      m[k][e.direction] += e.amount
    }
    return Object.values(m).sort((a, b) => a.month.localeCompare(b.month)).slice(-6)
  }, [entries])

  const topParties = useMemo(() => {
    const m = {}
    for (const e of entries) {
      if (e.direction !== 'expense') continue
      const key = e.vendor_name || e.party_name || 'Unassigned'
      m[key] = (m[key] || 0) + e.amount
    }
    return Object.entries(m).sort((a, b) => b[1] - a[1]).slice(0, 6)
  }, [entries])

  const maxParty = topParties[0]?.[1] || 1

  // ── Form ────────────────────────────────────────────────────────────────────
  const set = (k, v) => setDraft(d => {
    const next = { ...d, [k]: v }
    if (k === 'direction') next.category = (v === 'income' ? INCOME_CATS : EXPENSE_CATS)[0]
    return next
  })
  const openAdd  = () => { setEditId(null); setDraft(blank()); setShowForm(true); setTab('entries'); setError('') }
  const openEdit = e => {
    setEditId(e.id)
    setDraft({
      entry_date: e.entry_date, direction: e.direction, category: e.category, amount: String(e.amount),
      vendor_id: e.vendor_id || '', party_name: e.party_name || '', sku_id: e.sku_id || '',
      bank_name: e.bank_name || '', payment_method: e.payment_method || 'bank_transfer',
      reference_no: e.reference_no || '', note: e.note || '',
    })
    setShowForm(true); setTab('entries'); setError('')
  }
  const save = async () => {
    if (!draft.amount || Number(draft.amount) <= 0) { setError('Enter an amount greater than 0'); return }
    if (isAll && !editId && !newIn) { setError('Choose which company this entry belongs to'); return }
    setBusy(true); setError('')
    const payload = {
      ...draft, amount: Number(draft.amount),
      vendor_id: draft.vendor_id ? Number(draft.vendor_id) : null,
      sku_id: draft.sku_id ? Number(draft.sku_id) : null,
      party_name: draft.party_name.trim() || null, bank_name: draft.bank_name.trim() || null,
      reference_no: draft.reference_no.trim() || null, note: draft.note.trim() || null,
    }
    try {
      if (editId) await updateLedgerEntry(editId, payload)
      // In All Companies the picked company overrides the 'all' header for this request.
      else await createLedgerEntry(payload, isAll ? inCompany(newIn) : undefined)
      setShowForm(false); setEditId(null); setDraft(blank()); setNewIn(''); await load()
    } catch (err) { setError(errText(err, 'Save failed')) }
    finally { setBusy(false) }
  }
  const doRemove = async e => {
    try { await deleteLedgerEntry(e.id); await load() }
    catch (err) { setError(errText(err, 'Delete failed')) }
  }
  const remove = e => ask({
    title: 'Delete ledger entry',
    body: <>Delete this <strong>{e.direction}</strong> of <strong>{fmtP(e.amount)}</strong>
      {e.category ? <> in {e.category}</> : null}
      {/* In All Companies a row's owner is not obvious from context — say it before deleting. */}
      {e.company_name ? <> from <strong>{e.company_name}</strong></> : null}?
      <span className="cd-note">This cannot be undone.</span></>,
    confirmLabel: 'Delete entry', tone: 'danger',
    onConfirm: () => doRemove(e),
  })

  const exportCSV = () => {
    const cols = ['entry_date', 'direction', 'category', 'vendor_name', 'party_name', 'sku_code', 'amount', 'bank_name', 'payment_method', 'reference_no', 'note']
    const esc = v => `"${String(v ?? '').replace(/"/g, '""')}"`
    const csv = [cols.join(','), ...entries.map(e => cols.map(c => esc(e[c])).join(','))].join('\n')
    const a = document.createElement('a')
    a.href = URL.createObjectURL(new Blob([csv], { type: 'text/csv' }))
    a.download = `casper_expenses_${today()}.csv`
    a.click(); URL.revokeObjectURL(a.href)
  }

  const cats = draft.direction === 'income' ? INCOME_CATS : EXPENSE_CATS
  const thisMonth = monthly.find(m => m.month === monthKey(today()))?.expense || 0

  return (
    <div className="lg">
      {dialog}
      <header className="lg-head">
        <div>
          <h1 className="lg-title">Expense Ledger</h1>
          <p className="lg-sub">Every rupee in and out — categorised, by vendor, bank and SKU</p>
        </div>
        <div className="lg-head-actions">
          <button className="lg-btn-ghost" onClick={exportCSV} disabled={!entries.length}>Export CSV</button>
          <button className="lg-add-btn" onClick={openAdd}>+ New entry</button>
        </div>
      </header>

      {/* Stat cards */}
      <div className="lg-stats">
        <StatCard label="Total out" tone="out" value={fmt(summary.total_expense)} sub={`${summary.count} entries`}
          icon={<svg viewBox="0 0 20 20" width="16" height="16" fill="none" stroke="currentColor" strokeWidth="1.8" strokeLinecap="round" strokeLinejoin="round"><path d="M10 4v12M6 12l4 4 4-4"/></svg>} />
        <StatCard label="Total in" tone="in" value={fmt(summary.total_income)}
          icon={<svg viewBox="0 0 20 20" width="16" height="16" fill="none" stroke="currentColor" strokeWidth="1.8" strokeLinecap="round" strokeLinejoin="round"><path d="M10 16V4M6 8l4-4 4 4"/></svg>} />
        <StatCard label="Net" tone={summary.net >= 0 ? 'in' : 'out'} value={fmt(summary.net)} sub={summary.net >= 0 ? 'surplus' : 'deficit'}
          icon={<svg viewBox="0 0 20 20" width="16" height="16" fill="none" stroke="currentColor" strokeWidth="1.8" strokeLinecap="round" strokeLinejoin="round"><path d="M3 10h14M10 3v14"/></svg>} />
        <StatCard label="This month" tone="neutral" value={fmt(thisMonth)} sub="spent"
          icon={<svg viewBox="0 0 20 20" width="16" height="16" fill="none" stroke="currentColor" strokeWidth="1.8" strokeLinecap="round" strokeLinejoin="round"><rect x="3" y="4" width="14" height="13" rx="2"/><path d="M3 8h14M7 2v4M13 2v4"/></svg>} />
      </div>

      {/* Tabs */}
      <div className="lg-tabs">
        <button className={`lg-tab${tab === 'overview' ? ' on' : ''}`} onClick={() => setTab('overview')}>Reports</button>
        <button className={`lg-tab${tab === 'entries' ? ' on' : ''}`} onClick={() => setTab('entries')}>Entries</button>
        <button className={`lg-tab${tab === 'discrepancies' ? ' on' : ''}`} onClick={() => setTab('discrepancies')}>Bill Discrepancies</button>
      </div>

      {error && <div className="lg-error" role="alert">{error}</div>}

      {loading ? <div className="lg-loading"><div className="loader" style={{ width: 26, height: 26 }} /></div> : tab === 'discrepancies' ? (
        <BillDiscrepancies />
      ) : tab === 'overview' ? (
        /* ── REPORTS ─────────────────────────────────────────────────────── */
        summary.count === 0 ? (
          <div className="lg-empty"><p>No data yet — add entries to see reports.</p><button className="lg-add-btn" onClick={openAdd}>+ Record your first entry</button></div>
        ) : (
          <div className="lg-reports">
            <div className="lg-card">
              <div className="lg-card-h">Expense by category</div>
              {expenseByCat.length === 0 ? <div className="lg-card-empty">No expenses</div> : (
                <ResponsiveContainer width="100%" height={240}>
                  <PieChart>
                    <Pie data={expenseByCat} dataKey="value" nameKey="name" cx="50%" cy="50%" innerRadius={55} outerRadius={90} paddingAngle={2}>
                      {expenseByCat.map((e, i) => <Cell key={i} fill={e.color} stroke="none" />)}
                    </Pie>
                    <Tooltip formatter={v => fmtP(v)} />
                    <Legend iconType="circle" wrapperStyle={{ fontSize: 11 }} />
                  </PieChart>
                </ResponsiveContainer>
              )}
            </div>

            <div className="lg-card">
              <div className="lg-card-h">Monthly in vs out (last 6)</div>
              {monthly.length === 0 ? <div className="lg-card-empty">No data</div> : (
                <ResponsiveContainer width="100%" height={240}>
                  <BarChart data={monthly} margin={{ top: 8, right: 8, left: -12, bottom: 0 }}>
                    <XAxis dataKey="month" tick={{ fontSize: 11, fill: 'var(--muted)' }} tickLine={false} axisLine={false} />
                    <YAxis tick={{ fontSize: 10, fill: 'var(--muted)' }} tickLine={false} axisLine={false} tickFormatter={v => v >= 1000 ? `${v / 1000}k` : v} />
                    <Tooltip formatter={v => fmtP(v)} cursor={{ fill: 'rgba(0,0,0,.04)' }} />
                    <Legend iconType="circle" wrapperStyle={{ fontSize: 11 }} />
                    <Bar dataKey="income" name="In" fill="#1FA968" radius={[3, 3, 0, 0]} />
                    <Bar dataKey="expense" name="Out" fill="#EC2D6E" radius={[3, 3, 0, 0]} />
                  </BarChart>
                </ResponsiveContainer>
              )}
            </div>

            <div className="lg-card lg-card-wide">
              <div className="lg-card-h">Top expense parties</div>
              {topParties.length === 0 ? <div className="lg-card-empty">No expenses</div> : (
                <div className="lg-bars">
                  {topParties.map(([name, val]) => (
                    <div className="lg-bar-row" key={name}>
                      <span className="lg-bar-name" title={name}>{name}</span>
                      <div className="lg-bar-track"><div className="lg-bar-fill" style={{ width: `${(val / maxParty) * 100}%` }} /></div>
                      <span className="lg-bar-val">{fmt(val)}</span>
                    </div>
                  ))}
                </div>
              )}
            </div>
          </div>
        )
      ) : (
        /* ── ENTRIES ─────────────────────────────────────────────────────── */
        <>
          <div className="lg-filters">
            <label>From <input type="date" value={filter.start} onChange={e => setFilter(f => ({ ...f, start: e.target.value }))} /></label>
            <label>To <input type="date" value={filter.end} onChange={e => setFilter(f => ({ ...f, end: e.target.value }))} /></label>
            <label>Type
              <select value={filter.direction} onChange={e => setFilter(f => ({ ...f, direction: e.target.value }))}>
                <option value="">All</option><option value="expense">Expense</option><option value="income">Income</option>
              </select>
            </label>
            {(filter.start || filter.end || filter.direction) && <button className="lg-clear" onClick={() => setFilter({ start: '', end: '', direction: '' })}>Clear</button>}
          </div>

          {showForm && (
            <div className="lg-form">
              <div className="lg-form-grid">
                {isAll && !editId && (
                  <label>Company<select value={newIn} onChange={e => setNewIn(e.target.value)}>
                    <option value="">— choose —</option>
                    {companies.map(c => <option key={c.id} value={c.id}>{c.name}</option>)}
                  </select></label>
                )}
                <label>Date<input type="date" value={draft.entry_date} onChange={e => set('entry_date', e.target.value)} /></label>
                <label>Type<select value={draft.direction} onChange={e => set('direction', e.target.value)}><option value="expense">Expense (out)</option><option value="income">Income (in)</option></select></label>
                <label>Category<select value={draft.category} onChange={e => set('category', e.target.value)}>{cats.map(c => <option key={c} value={c}>{label(c)}</option>)}</select></label>
                <label>Amount ₹<input type="number" min="0" step="0.01" value={draft.amount} onChange={e => set('amount', e.target.value)} placeholder="0.00" /></label>
                <label>Vendor<select value={draft.vendor_id} onChange={e => set('vendor_id', e.target.value)}><option value="">— none —</option>{vendors.map(v => <option key={v.id} value={v.id}>{v.name}</option>)}</select></label>
                <label>Party name<input value={draft.party_name} onChange={e => set('party_name', e.target.value)} placeholder="if not a saved vendor" /></label>
                <label>SKU<select value={draft.sku_id} onChange={e => set('sku_id', e.target.value)}><option value="">— none —</option>{skus.map(s => <option key={s.id} value={s.id}>{s.shringar_sku}</option>)}</select></label>
                <label>Bank name<input value={draft.bank_name} onChange={e => set('bank_name', e.target.value)} placeholder="e.g. HDFC Bank" /></label>
                <label>Payment method<select value={draft.payment_method} onChange={e => set('payment_method', e.target.value)}>{METHODS.map(m => <option key={m} value={m}>{label(m)}</option>)}</select></label>
                <label>Reference no<input value={draft.reference_no} onChange={e => set('reference_no', e.target.value)} placeholder="txn / invoice / cheque" /></label>
                <label className="lg-note-field">Note<input value={draft.note} onChange={e => set('note', e.target.value)} placeholder="optional" /></label>
              </div>
              <div className="lg-form-actions">
                <button className="lg-save" onClick={save} disabled={busy}>{busy ? 'Saving…' : editId ? 'Update entry' : 'Add entry'}</button>
                <button className="lg-cancel" onClick={() => { setShowForm(false); setEditId(null) }}>Cancel</button>
              </div>
            </div>
          )}

          {entries.length === 0 ? (
            <div className="lg-empty"><p>No ledger entries yet.</p><button className="lg-add-btn" onClick={openAdd}>+ Record your first entry</button></div>
          ) : (
            <div className="lg-table-wrap">
              <table className="lg-table">
                <thead><tr><th>Date</th><th>Type</th><th>Category</th><th>Party</th><th>SKU</th><th className="num">Amount</th><th>Bank</th><th>Method</th><th>Ref</th><th>Note</th><th></th></tr></thead>
                <tbody>
                  {entries.map(e => (
                    // company_name is sent only when the list spans several companies,
                    // so the rail appears exactly when rows could be confused.
                    <tr key={e.id}
                        className={e.company_name ? 'co-rail' : undefined}
                        title={e.company_name || undefined}
                        style={e.company_color ? { '--co-mark': e.company_color } : undefined}>
                      <td className="mono">{e.entry_date}</td>
                      <td><span className={`lg-dir ${e.direction}`}>{e.direction === 'income' ? 'In' : 'Out'}</span></td>
                      <td>{label(e.category)}</td>
                      <td>{e.vendor_name || e.party_name || '—'}</td>
                      <td className="mono">{e.sku_code || '—'}</td>
                      <td className={`num mono ${e.direction}`}>{e.direction === 'income' ? '+' : '−'}{fmtP(e.amount)}</td>
                      <td>{e.bank_name || '—'}</td>
                      <td>{label(e.payment_method) || '—'}</td>
                      <td className="mono">{e.reference_no || '—'}</td>
                      <td className="lg-note-cell" title={e.note || ''}>{e.note || '—'}</td>
                      <td className="lg-actions">
                        <button className="lg-edit" onClick={() => openEdit(e)} aria-label="Edit entry">✎</button>
                        <button className="lg-del" onClick={() => remove(e)} aria-label="Delete entry">✕</button>
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          )}
        </>
      )}
    </div>
  )
}

import { useState } from 'react'
import { useNavigate, Link } from 'react-router-dom'
import { useAuth } from '../context/AuthContext'
import './Login.css'

export default function Login() {
  const [email,    setEmail]    = useState('')
  const [password, setPassword] = useState('')
  const [error,    setError]    = useState('')
  const [loading,  setLoading]  = useState(false)
  const { login }  = useAuth()
  const navigate   = useNavigate()

  const handleSubmit = async e => {
    e.preventDefault()
    setError(''); setLoading(true)
    try {
      await login(email, password)
      navigate('/')
    } catch (err) {
      // Only a 4xx from the server means the credentials were actually wrong.
      // With no response at all (backend down, proxy timeout) `detail` is
      // undefined, and defaulting to "Invalid credentials" sends you off
      // checking your password when the server simply is not running.
      if (!err.response) {
        setError('Cannot reach the server. Is the backend running on port 8765?')
      } else if (err.response.status >= 500) {
        setError(`Server error (${err.response.status}). Check the backend log.`)
      } else {
        const detail = err.response.data?.detail
        setError(Array.isArray(detail) ? 'Invalid credentials' : (detail || 'Invalid credentials'))
      }
    } finally {
      setLoading(false)
    }
  }

  return (
    <div className="login-page">
      <div className="login-box">
        <div className="login-logo">C</div>
        <div className="login-brand">Casper</div>
        <div className="login-tagline">Pricing intelligence for ecommerce sellers</div>

        <form onSubmit={handleSubmit} className="login-form">
          <div className="input-group">
            <label htmlFor="login-email">Email</label>
            <input id="login-email" className="input" type="email" placeholder="admin@casper.com"
              value={email} onChange={e => setEmail(e.target.value)} required autoFocus />
          </div>
          <div className="input-group">
            <label htmlFor="login-password">Password</label>
            <input id="login-password" className="input" type="password" placeholder="••••••••"
              value={password} onChange={e => setPassword(e.target.value)} required />
          </div>
          {error && <div className="login-error">{error}</div>}
          <button className="btn btn-primary login-submit" type="submit" disabled={loading}>
            {loading && (
              <span className="loader" style={{ width:13, height:13, borderWidth:2,
                borderTopColor:'rgba(255,255,255,0.8)', borderColor:'rgba(255,255,255,0.2)' }}/>
            )}
            {loading ? 'Signing in…' : 'Sign in'}
          </button>
        </form>

        <div className="login-footer">
          New to Casper? <Link to="/register" className="login-link">Create an account</Link>
        </div>
      </div>
    </div>
  )
}

import { useState, useEffect, useCallback } from 'react'
import { useParams, useSearchParams, useNavigate } from 'react-router-dom'
import { getPnlReport } from '../../api/client'
import { fmtPeriod }      from './flipkart/utils'
import { useFlipkartData } from './flipkart/useFlipkartData'
import FlipkartOverview   from './flipkart/FlipkartOverview'
import ProfitLossView     from './flipkart/ProfitLossView'
import OperatingPnLView   from './flipkart/OperatingPnLView'
import InsightsPanel      from './flipkart/InsightsPanel'
import './Flipkart.css'

const VIEWS       = ['fk', 'pnl', 'ops', 'insights']
const VIEW_LABELS = ['Flipkart Report', 'Profit & Loss', 'Operating P&L', 'Insights']

/**
 * Top-level route component for /pnl/flipkart/:reportId.
 * Owns: fetching, tab state, refresh button.
 * Delegates rendering to tab-specific children.
 */
export default function FlipkartReport() {
  const { reportId }                    = useParams()
  const [searchParams, setSearchParams] = useSearchParams()
  const navigate                        = useNavigate()

  const view     = VIEWS.includes(searchParams.get('view')) ? searchParams.get('view') : 'fk'
  const tabIndex = VIEWS.indexOf(view)

  const [report,  setReport]  = useState(null)
  const [loading, setLoading] = useState(true)
  const [error,   setError]   = useState(null)

  const fetchReport = useCallback((showLoader = true) => {
    if (showLoader) setLoading(true)
    setError(null)
    getPnlReport(Number(reportId))
      .then(data => { setReport(data); setLoading(false) })
      .catch(() => { setError('Report not found'); setLoading(false) })
  }, [reportId])

  useEffect(() => { fetchReport() }, [fetchReport])

  // Refetch on tab visibility change — catches SKU edits made in another tab
  useEffect(() => {
    const onVisible = () => {
      if (document.visibilityState === 'visible') fetchReport(false)
    }
    document.addEventListener('visibilitychange', onVisible)
    return () => document.removeEventListener('visibilitychange', onVisible)
  }, [fetchReport])

  const { augmentedRows, insightsData } = useFlipkartData(report)

  const setView = v => setSearchParams({ view: v }, { replace: true })

  if (loading) return (
    <div className="pnl-page"><div className="pnl-empty">Loading report…</div></div>
  )
  if (error) return (
    <div className="pnl-page">
      <div className="pnl-empty-state">
        <div className="pnl-empty-icon">⚠</div>
        <div className="pnl-empty-title">{error}</div>
        <button className="pnl-btn-ghost" onClick={() => navigate('/pnl/flipkart')}>← Back to Reports</button>
      </div>
    </div>
  )

  return (
    <div className="pnl-page">

      {/* ── Header ── */}
      <div className="pnl-header">
        <div className="pnl-title-row">
          <div>
            <div style={{ display: 'flex', alignItems: 'center', gap: 8, marginBottom: 6 }}>
              <button className="pnl-btn-ghost" style={{ fontSize: 11, padding: '3px 10px' }}
                onClick={() => navigate('/pnl/flipkart')}>← Reports</button>
              <div className="pnl-platform-badge"><span className="pnl-fk-dot"/>Flipkart</div>
            </div>
            <h1 className="pnl-title">{fmtPeriod(report.period_start, report.period_end)}</h1>
            <div style={{ fontSize: 11, color: 'var(--text-3)', marginTop: 2 }}>{report.filename}</div>
          </div>
          <button
            className="pnl-btn-ghost"
            style={{ fontSize: 11, padding: '4px 12px', alignSelf: 'flex-start' }}
            onClick={() => fetchReport(false)}
            title="Refetch live pricing from Casper">
            ↻ Refresh
          </button>
        </div>
        <div className="pnl-tabs">
          {VIEW_LABELS.map((label, i) => (
            <button key={label} className={`pnl-tab${tabIndex === i ? ' active' : ''}`}
              onClick={() => setView(VIEWS[i])}>{label}</button>
          ))}
        </div>
      </div>

      {view === 'fk'       && <FlipkartOverview report={report} insightsData={insightsData} onViewPnL={() => setView('pnl')} />}
      {view === 'pnl'      && <ProfitLossView    report={report} augmentedRows={augmentedRows} />}
      {view === 'ops'      && <OperatingPnLView  report={report} onRefresh={() => fetchReport(false)} />}
      {view === 'insights' && <InsightsPanel    report={report} insightsData={insightsData} />}

    </div>
  )
}

import { useState, useEffect, useMemo, useRef } from 'react'
import { useParams, useNavigate } from 'react-router-dom'
import { getPlatforms, getPnlReports, uploadPnlReport, deletePnlReport } from '../../api/client'
import './Flipkart.css'
import { useConfirm } from '../../components/ConfirmDialog'

const TABS = ['Reports', 'All Time P&L', 'By SKU']

const fmt = (v, d = 0) => {
  if (v == null) return '—'
  const n = Number(v)
  const abs = Math.abs(n).toLocaleString('en-IN', { minimumFractionDigits: d, maximumFractionDigits: d })
  return (n < 0 ? '-' : '') + '₹' + abs
}
const fmtN   = v => v == null ? '—' : Number(v).toLocaleString('en-IN')
const fmtPct = v => v == null ? '—' : Number(v).toFixed(1) + '%'
const parseLocalDate = s => s ? new Date(s + 'T00:00:00') : null
const fmtPeriod = (start, end) => {
  const s = parseLocalDate(start), e = parseLocalDate(end)
  if (!s || !e) return '—'
  return `${s.toLocaleDateString('en-IN', { month: 'short', year: 'numeric' })} — ${e.toLocaleDateString('en-IN', { day: 'numeric', month: 'short', year: 'numeric' })}`
}

const PLATFORM_COLORS = {
  flipkart:  '#F9A825',
  meesho:    '#9C27B0',
  snapdeal:  '#E53935',
  amazon:    '#FF9900',
}

export default function PnLList() {
  const { ask, dialog } = useConfirm()
  const { platform }  = useParams()
  const navigate      = useNavigate()
  const fileRef       = useRef(null)

  const platformKey   = (platform || '').toLowerCase()
  const dotColor      = PLATFORM_COLORS[platformKey] || '#6B7280'
  const capitalize    = s => s ? s.charAt(0).toUpperCase() + s.slice(1) : s

  const [tab,            setTab]           = useState(0)
  const [viewMode,       setViewMode]      = useState('grid')
  const [reports,        setReports]       = useState([])
  const [platformId,     setPlatformId]    = useState(null)
  const [platformName,   setPlatformName]  = useState(capitalize(platform || ''))
  const [loadingReports, setLoadingReports] = useState(true)
  const [showUpload,     setShowUpload]    = useState(false)
  const [uploading,      setUploading]     = useState(false)
  const [uploadError,    setUploadError]   = useState('')
  const [file,           setFile]          = useState(null)
  const [toast,          setToast]         = useState(null)
  const [conflict,       setConflict]      = useState(null)
  const [uploadResult,   setUploadResult]  = useState(null)   // holds result when parse warnings exist

  useEffect(() => {
    setTab(0)
    setReports([])
    setLoadingReports(true)
    setPlatformId(null)

    async function init() {
      try {
        const platforms = await getPlatforms()
        const found = platforms.find(p => p.name.toLowerCase() === platformKey)
        if (found) {
          setPlatformId(found.id)
          setPlatformName(found.name)
          setReports(await getPnlReports(found.id))
        }
      } catch (e) { console.error('[PnL]', e) }
      finally { setLoadingReports(false) }
    }
    init()
  }, [platformKey])

  function showToast(msg, type = 'success') {
    setToast({ msg, type })
    setTimeout(() => setToast(null), 3500)
  }

  async function handleUpload(force = false) {
    if (!file)       { setUploadError('Please select a file.'); return }
    if (!platformId) { setUploadError(`${platformName} platform not found.`); return }
    setUploading(true); setUploadError('')
    try {
      const fd = new FormData()
      fd.append('file', file); fd.append('platform_id', platformId); fd.append('force', force)
      const result = await uploadPnlReport(fd)
      setReports(await getPnlReports(platformId))
      setConflict(null); setFile(null)
      if (result.parse_warnings?.length > 0) {
        // Stay in modal, show warnings — user must acknowledge before navigating
        setUploadResult(result)
      } else {
        setShowUpload(false)
        showToast(`Uploaded — ${result.matched_skus} matched, ${result.unmatched_skus} unmatched`)
        navigate(`/pnl/${platformKey}/${result.report_id}?view=pnl`)
      }
    } catch (err) {
      if (err.response?.status === 409) { setConflict(err.response.data.detail) }
      else {
        const d = err.response?.data?.detail
        setUploadError(typeof d === 'string' ? d : Array.isArray(d) ? d.map(e => e.msg).join(' · ') : 'Upload failed.')
      }
    } finally { setUploading(false) }
  }

  function closeUpload() {
    if (uploading) return
    setShowUpload(false); setUploadError(''); setFile(null); setUploadResult(null)
  }

  function goToUploadResult() {
    const r = uploadResult
    setShowUpload(false); setUploadResult(null)
    showToast(`Uploaded — ${r.matched_skus} matched, ${r.unmatched_skus} unmatched`, 'success')
    navigate(`/pnl/${platformKey}/${r.report_id}?view=pnl`)
  }

  function handleDelete(reportId, e) {
    e.stopPropagation()
    ask({
      title: 'Delete report',
      body: <>Delete this report and every SKU row in it?
        <span className="cd-note">Its P&amp;L, settlement and fraud data go with it. This cannot be undone.</span></>,
      confirmLabel: 'Delete report', tone: 'danger',
      onConfirm: () => doDelete(reportId),
    })
  }

  async function doDelete(reportId) {
    try {
      await deletePnlReport(reportId)
      setReports(r => r.filter(x => x.id !== reportId))
      showToast('Report deleted', 'info')
    } catch { showToast('Failed to delete', 'error') }
  }

  const lifetimeData = useMemo(() => {
    if (!reports.length) return null
    return {
      totalBS:         reports.reduce((s, r) => s + (r.bank_settlement || 0), 0),
      totalNetSales:   reports.reduce((s, r) => s + (r.net_sales || 0), 0),
      totalGross:      reports.reduce((s, r) => s + (r.gross_sales || 0), 0),
      totalNetUnits:   reports.reduce((s, r) => s + (r.net_units || 0), 0),
      totalGrossUnits: reports.reduce((s, r) => s + (r.gross_units || 0), 0),
      avgMargin:       reports.reduce((s, r) => s + (r.net_margin_pct || 0), 0) / reports.length,
      sorted:          [...reports].sort((a, b) => parseLocalDate(b.period_start) - parseLocalDate(a.period_start)),
    }
  }, [reports])

  return (
    <div className="pnl-page">
      {dialog}

      {toast && <div className={`pnl-toast pnl-toast-${toast.type}`}>{toast.msg}</div>}

      {/* ── Header ── */}
      <div className="pnl-header">
        <div className="pnl-title-row">
          <div>
            <div className="pnl-platform-badge">
              <span className="pnl-fk-dot" style={{ background: dotColor }} />
              {platformName}
            </div>
            <h1 className="pnl-title">Profit &amp; Loss</h1>
          </div>
          <button className="pnl-upload-btn" onClick={() => { setShowUpload(true); setUploadError('') }}>
            + Upload Report
          </button>
        </div>
        <div className="pnl-tabs">
          {TABS.map((t, i) => (
            <button key={t} className={`pnl-tab${tab === i ? ' active' : ''}`} onClick={() => setTab(i)}>{t}</button>
          ))}
        </div>
      </div>

      {/* ── Tab 0: Reports ── */}
      {tab === 0 && (
        <div className="pnl-body">
          {loadingReports ? (
            <div className="pnl-empty">Loading reports…</div>
          ) : reports.length === 0 ? (
            <div className="pnl-empty-state">
              <div className="pnl-empty-icon">
                <svg viewBox="0 0 40 40" fill="none" stroke="currentColor" strokeWidth="1.4" strokeLinecap="round"><rect x="5" y="5" width="30" height="30" rx="4"/><path d="M12 28v-8M20 28V15M28 28v-5"/></svg>
              </div>
              <div className="pnl-empty-title">No reports yet</div>
              <div className="pnl-empty-sub">Upload your first {platformName} P&amp;L report to get started</div>
              <button className="pnl-upload-btn" onClick={() => setShowUpload(true)}>+ Upload Report</button>
            </div>
          ) : (
            <>
              <div className="pnl-view-bar">
                <span className="pnl-report-count">{reports.length} report{reports.length !== 1 ? 's' : ''}</span>
                <div className="pnl-view-toggle">
                  <button className={`pnl-view-btn${viewMode === 'grid' ? ' active' : ''}`} onClick={() => setViewMode('grid')} title="Grid">
                    <svg width="14" height="14" viewBox="0 0 14 14" fill="none"><rect x="0" y="0" width="6" height="6" rx="1.5" fill="currentColor"/><rect x="8" y="0" width="6" height="6" rx="1.5" fill="currentColor"/><rect x="0" y="8" width="6" height="6" rx="1.5" fill="currentColor"/><rect x="8" y="8" width="6" height="6" rx="1.5" fill="currentColor"/></svg>
                  </button>
                  <button className={`pnl-view-btn${viewMode === 'list' ? ' active' : ''}`} onClick={() => setViewMode('list')} title="List">
                    <svg width="14" height="14" viewBox="0 0 14 14" fill="none"><rect x="0" y="1" width="14" height="2" rx="1" fill="currentColor"/><rect x="0" y="6" width="14" height="2" rx="1" fill="currentColor"/><rect x="0" y="11" width="14" height="2" rx="1" fill="currentColor"/></svg>
                  </button>
                </div>
              </div>

              {/* Grid */}
              {viewMode === 'grid' && (
                <div className="pnl-cards">
                  {reports.map(r => (
                    <div key={r.id} className="pnl-card">
                      <div className="pnl-card-top">
                        <div>
                          <div className="pnl-card-period">{fmtPeriod(r.period_start, r.period_end)}</div>
                          <div className="pnl-card-filename">{r.filename}</div>
                        </div>
                        <button className="pnl-card-del" onClick={e => handleDelete(r.id, e)}>✕</button>
                      </div>
                      <div className="pnl-card-metrics">
                        <div className="pnl-metric"><div className="pnl-metric-label">Gross Sales</div><div className="pnl-metric-val">{fmt(r.gross_sales)}</div></div>
                        <div className="pnl-metric"><div className="pnl-metric-label">Net Sales</div><div className="pnl-metric-val">{fmt(r.net_sales)}</div></div>
                        <div className="pnl-metric"><div className="pnl-metric-label">Bank Settlement</div><div className="pnl-metric-val gold">{fmt(r.bank_settlement)}</div></div>
                        <div className="pnl-metric"><div className="pnl-metric-label">{platformName} Margin</div><div className="pnl-metric-val">{fmtPct(r.net_margin_pct)}</div></div>
                      </div>
                      <div className="pnl-card-footer">
                        <span className="pnl-units">{fmtN(r.gross_units)} gross · {fmtN(r.net_units)} net units</span>
                        <div className="pnl-match-pills">
                          <span className="pnl-pill matched">{r.matched_skus} matched</span>
                          {r.unmatched_skus > 0 && <span className="pnl-pill unmatched">{r.unmatched_skus} unmatched</span>}
                        </div>
                      </div>
                      <div className="pnl-card-actions">
                        <button className="pnl-card-action-btn"
                          onClick={() => navigate(`/pnl/${platformKey}/${r.id}?view=overview`)}>
                          {platformName} Report
                        </button>
                        <button className="pnl-card-action-btn pnl-card-action-pnl"
                          onClick={() => navigate(`/pnl/${platformKey}/${r.id}?view=pnl`)}>
                          Real P&amp;L
                        </button>
                      </div>
                    </div>
                  ))}
                </div>
              )}

              {/* List */}
              {viewMode === 'list' && (
                <div className="pnl-list">
                  <div className="pnl-list-header">
                    <div className="pnl-lh-period">Period</div>
                    <div className="pnl-lh-num">Gross Sales</div>
                    <div className="pnl-lh-num">Net Sales</div>
                    <div className="pnl-lh-num">Bank Settlement</div>
                    <div className="pnl-lh-num">{platformName} Margin</div>
                    <div className="pnl-lh-num">Units</div>
                    <div className="pnl-lh-pills">SKUs</div>
                    <div className="pnl-lh-act">Actions</div>
                  </div>
                  {reports.map(r => (
                    <div key={r.id} className="pnl-list-row">
                      <div className="pnl-lc-period">
                        <div className="pnl-lc-period-main">{fmtPeriod(r.period_start, r.period_end)}</div>
                        <div className="pnl-lc-filename">{r.filename}</div>
                      </div>
                      <div className="pnl-lc-num">{fmt(r.gross_sales)}</div>
                      <div className="pnl-lc-num">{fmt(r.net_sales)}</div>
                      <div className="pnl-lc-num gold">{fmt(r.bank_settlement)}</div>
                      <div className="pnl-lc-num">
                        <span className={`pnl-margin-badge ${(r.net_margin_pct||0) >= 70 ? 'good' : (r.net_margin_pct||0) >= 40 ? 'mid' : 'low'}`}>{fmtPct(r.net_margin_pct)}</span>
                      </div>
                      <div className="pnl-lc-num muted">{fmtN(r.gross_units)} / {fmtN(r.net_units)}</div>
                      <div className="pnl-lc-pills">
                        <span className="pnl-pill matched">{r.matched_skus}M</span>
                        {r.unmatched_skus > 0 && <span className="pnl-pill unmatched" style={{ marginLeft: 4 }}>{r.unmatched_skus}U</span>}
                      </div>
                      <div className="pnl-lc-act pnl-list-actions">
                        <button className="pnl-list-action-btn"
                          onClick={() => navigate(`/pnl/${platformKey}/${r.id}?view=overview`)}>Report</button>
                        <button className="pnl-list-action-btn pnl-list-action-pnl"
                          onClick={() => navigate(`/pnl/${platformKey}/${r.id}?view=pnl`)}>P&amp;L</button>
                        <button className="pnl-card-del" onClick={e => handleDelete(r.id, e)}>✕</button>
                      </div>
                    </div>
                  ))}
                </div>
              )}
            </>
          )}
        </div>
      )}

      {/* ── Tab 1: All Time P&L ── */}
      {tab === 1 && (
        <div className="pnl-body pnl-animate-in">
          {!lifetimeData ? (
            <div className="pnl-empty-state">
              <div className="pnl-empty-icon">
                <svg viewBox="0 0 40 40" fill="none" stroke="currentColor" strokeWidth="1.4" strokeLinecap="round"><rect x="5" y="5" width="30" height="30" rx="4"/><path d="M12 28v-8M20 28V15M28 28v-5"/></svg>
              </div>
              <div className="pnl-empty-title">No reports yet</div>
              <div className="pnl-empty-sub">Upload reports to see lifetime P&amp;L</div>
              <button className="pnl-btn-ghost" onClick={() => setTab(0)}>← Go to Reports</button>
            </div>
          ) : (
            <div className="pnl-animate-in">
              <div className="pnl-lt-kpis">
                <div className="pnl-lt-kpi">
                  <div className="pnl-lt-kpi-label">Total Bank Settlement</div>
                  <div className="pnl-lt-kpi-val gold">{fmt(lifetimeData.totalBS)}</div>
                  <div className="pnl-lt-kpi-sub">Across {reports.length} report{reports.length !== 1 ? 's' : ''}</div>
                </div>
                <div className="pnl-lt-kpi">
                  <div className="pnl-lt-kpi-label">Total Net Sales</div>
                  <div className="pnl-lt-kpi-val">{fmt(lifetimeData.totalNetSales)}</div>
                  <div className="pnl-lt-kpi-sub">After all returns</div>
                </div>
                <div className="pnl-lt-kpi">
                  <div className="pnl-lt-kpi-label">Total Units Delivered</div>
                  <div className="pnl-lt-kpi-val">{fmtN(lifetimeData.totalNetUnits)}</div>
                  <div className="pnl-lt-kpi-sub">of {fmtN(lifetimeData.totalGrossUnits)} ordered</div>
                </div>
                <div className="pnl-lt-kpi">
                  <div className="pnl-lt-kpi-label">Avg {platformName} Margin</div>
                  <div className="pnl-lt-kpi-val">{fmtPct(lifetimeData.avgMargin)}</div>
                  <div className="pnl-lt-kpi-sub">After {platformName} fees only</div>
                </div>
              </div>

              <div className="pnl-lt-section">
                <div className="pnl-lt-section-title">Period Breakdown</div>
                <div className="pnl-tbl-wrap" style={{ flex: 'none' }}>
                  <table className="pnl-tbl">
                    <thead>
                      <tr>
                        <th className="pnl-th">Period</th>
                        <th className="pnl-th" style={{ textAlign: 'right' }}>Gross Sales</th>
                        <th className="pnl-th" style={{ textAlign: 'right' }}>Net Sales</th>
                        <th className="pnl-th" style={{ textAlign: 'right' }}>Bank Settlement</th>
                        <th className="pnl-th" style={{ textAlign: 'right' }}>{platformName} Margin</th>
                        <th className="pnl-th" style={{ textAlign: 'right' }}>Gross Units</th>
                        <th className="pnl-th" style={{ textAlign: 'right' }}>Net Units</th>
                        <th className="pnl-th" style={{ textAlign: 'center' }}>SKUs</th>
                        <th className="pnl-th" style={{ textAlign: 'center' }}>Open</th>
                      </tr>
                    </thead>
                    <tbody>
                      {lifetimeData.sorted.map(r => (
                        <tr key={r.id} className="pnl-tr pnl-lt-row">
                          <td className="pnl-td"><div className="pnl-lt-period">{fmtPeriod(r.period_start, r.period_end)}</div></td>
                          <td className="pnl-td right mono">{fmt(r.gross_sales)}</td>
                          <td className="pnl-td right mono">{fmt(r.net_sales)}</td>
                          <td className="pnl-td right mono gold">{fmt(r.bank_settlement)}</td>
                          <td className="pnl-td center">
                            <span className={`pnl-margin-badge ${(r.net_margin_pct||0) >= 70 ? 'good' : (r.net_margin_pct||0) >= 40 ? 'mid' : 'low'}`}>{fmtPct(r.net_margin_pct)}</span>
                          </td>
                          <td className="pnl-td right mono muted">{fmtN(r.gross_units)}</td>
                          <td className="pnl-td right mono">{fmtN(r.net_units)}</td>
                          <td className="pnl-td center">
                            <span className="pnl-pill matched">{r.matched_skus}M</span>
                            {r.unmatched_skus > 0 && <span className="pnl-pill unmatched" style={{ marginLeft: 4 }}>{r.unmatched_skus}U</span>}
                          </td>
                          <td className="pnl-td center">
                            <div className="pnl-lt-btns">
                              <button className="pnl-lt-open-btn" title={`${platformName} Report`}
                                onClick={() => navigate(`/pnl/${platformKey}/${r.id}?view=overview`)}>↗</button>
                              <button className="pnl-lt-open-btn pnl-lt-open-pnl" title="Unit Economics"
                                onClick={() => navigate(`/pnl/${platformKey}/${r.id}?view=pnl`)}>P&L</button>
                            </div>
                          </td>
                        </tr>
                      ))}
                    </tbody>
                    <tfoot>
                      <tr className="pnl-lt-totals">
                        <td className="pnl-td pnl-lt-total-label">Total</td>
                        <td className="pnl-td right mono">{fmt(lifetimeData.totalGross)}</td>
                        <td className="pnl-td right mono">{fmt(lifetimeData.totalNetSales)}</td>
                        <td className="pnl-td right mono gold">{fmt(lifetimeData.totalBS)}</td>
                        <td className="pnl-td center">
                          <span className={`pnl-margin-badge ${lifetimeData.avgMargin >= 70 ? 'good' : lifetimeData.avgMargin >= 40 ? 'mid' : 'low'}`}>{fmtPct(lifetimeData.avgMargin)} avg</span>
                        </td>
                        <td className="pnl-td right mono muted">{fmtN(lifetimeData.totalGrossUnits)}</td>
                        <td className="pnl-td right mono">{fmtN(lifetimeData.totalNetUnits)}</td>
                        <td className="pnl-td center">—</td>
                        <td className="pnl-td center">—</td>
                      </tr>
                    </tfoot>
                  </table>
                </div>
              </div>
            </div>
          )}
        </div>
      )}

      {/* ── Tab 2: By SKU ── */}
      {tab === 2 && (
        <div className="pnl-body pnl-animate-in pnl-empty-state">
          <div className="pnl-empty-icon">
            <svg viewBox="0 0 40 40" fill="none" stroke="currentColor" strokeWidth="1.4" strokeLinecap="round"><circle cx="20" cy="20" r="14"/><path d="M20 13v7l5 3"/></svg>
          </div>
          <div className="pnl-empty-title">Lifetime By SKU</div>
          <div className="pnl-empty-sub">Cross-report SKU performance — coming soon</div>
        </div>
      )}

      {/* ── Upload modal ── */}
      {showUpload && !conflict && (
        <div className="pnl-modal-overlay" onClick={closeUpload}>
          <div className="pnl-modal" onClick={e => e.stopPropagation()}>
            <div className="pnl-modal-hdr">
              <span>Upload {platformName} P&amp;L Report</span>
              <button className="pnl-modal-close" onClick={closeUpload}>✕</button>
            </div>
            <div className="pnl-modal-body">
              <div className="pnl-period-note">Period will be auto-detected from the report file.</div>
              <div className="pnl-field">
                <label className="pnl-label">Excel File (.xlsx / .xls)</label>
                <div className={`pnl-dropzone${file ? ' has-file' : ''}`}
                  onClick={() => fileRef.current?.click()}
                  onDragOver={e => e.preventDefault()}
                  onDrop={e => { e.preventDefault(); const f = e.dataTransfer.files[0]; if (f) setFile(f) }}>
                  {file ? (
                    <>
                      <span className="pnl-file-icon">
                        <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.5" strokeLinecap="round" strokeLinejoin="round" width="22" height="22"><path d="M14 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8z"/><polyline points="14 2 14 8 20 8"/></svg>
                      </span>
                      <span className="pnl-file-name">{file.name}</span>
                      <button className="pnl-file-clear" onClick={e => { e.stopPropagation(); setFile(null) }}>✕ Clear</button>
                    </>
                  ) : (
                    <>
                      <span className="pnl-drop-icon">⬆</span>
                      <span>Drop file here or click to browse</span>
                      <span className="pnl-drop-hint">{platformName} P&amp;L .xlsx</span>
                    </>
                  )}
                  <input ref={fileRef} type="file" accept=".xlsx,.xls" style={{ display: 'none' }}
                    onChange={e => setFile(e.target.files[0])} />
                </div>
              </div>
              {uploadError && <div className="pnl-error">{uploadError}</div>}

              {/* Parse warnings — shown after upload if critical fields have >30% nulls */}
              {uploadResult?.parse_warnings?.length > 0 && (
                <div className="pnl-parse-warnings">
                  <div className="pnl-warn-head">
                    <svg width="14" height="14" viewBox="0 0 20 20" fill="currentColor"><path d="M10 2L1 17h18L10 2zm0 3l6.5 11H3.5L10 5zm-1 4v3h2V9H9zm0 4v2h2v-2H9z"/></svg>
                    Upload successful — {uploadResult.matched_skus} matched · {uploadResult.unmatched_skus} unmatched
                  </div>
                  <div className="pnl-warn-title">⚠ Data quality issues detected</div>
                  {uploadResult.parse_warnings.map((w, i) => (
                    <div key={i} className="pnl-warn-item">• {w}</div>
                  ))}
                  <div className="pnl-warn-note">These fields may affect P&L accuracy. Check the parser or re-upload a corrected file.</div>
                </div>
              )}
            </div>
            <div className="pnl-modal-footer">
              {uploadResult ? (
                <>
                  <button className="pnl-btn-ghost" onClick={closeUpload}>Close</button>
                  <button className="pnl-btn-primary" onClick={goToUploadResult}>View Report →</button>
                </>
              ) : (
                <>
                  <button className="pnl-btn-ghost" onClick={closeUpload} disabled={uploading}>Cancel</button>
                  <button className="pnl-btn-primary" onClick={() => handleUpload(false)} disabled={uploading || !file}>
                    {uploading ? 'Uploading…' : 'Upload'}
                  </button>
                </>
              )}
            </div>
          </div>
        </div>
      )}

      {/* ── Conflict modal ── */}
      {conflict && (
        <div className="pnl-modal-overlay" onClick={() => !uploading && setConflict(null)}>
          <div className="pnl-modal" onClick={e => e.stopPropagation()}>
            <div className="pnl-modal-hdr"><span>⚠ Duplicate Report Detected</span></div>
            <div className="pnl-modal-body">
              <div className="pnl-conflict-info">
                <div>A report for this period already exists:</div>
                <div className="pnl-conflict-detail">
                  <div><b>Period:</b> {conflict.period_start} → {conflict.period_end}</div>
                  <div><b>Uploaded:</b> {new Date(conflict.uploaded_at).toLocaleString('en-IN')}</div>
                  <div><b>File:</b> {conflict.filename}</div>
                </div>
                <div className="pnl-conflict-warn">Replacing will permanently delete the existing report and all its data.</div>
              </div>
            </div>
            <div className="pnl-modal-footer">
              <button className="pnl-btn-ghost" onClick={() => setConflict(null)}>Keep Existing</button>
              <button className="pnl-btn-danger" onClick={() => { setConflict(null); handleUpload(true) }} disabled={uploading}>
                {uploading ? 'Replacing…' : 'Replace'}
              </button>
            </div>
          </div>
        </div>
      )}

    </div>
  )
}

import { useState, useEffect, useCallback } from 'react'
import { useParams, useSearchParams, useNavigate } from 'react-router-dom'
import { getPnlReport } from '../../api/client'
import { fmtPeriod }     from './flipkart/utils'
import { useReportData } from './flipkart/useReportData'
import IncomeStatement   from './flipkart/IncomeStatement'
import ReportOverview    from './flipkart/ReportOverview'
import ProfitLossView    from './flipkart/ProfitLossView'
import OperatingPnLView  from './flipkart/OperatingPnLView'
import InsightsPanel     from './flipkart/InsightsPanel'
import './Flipkart.css'

const PLATFORM_COLORS = {
  flipkart: '#F9A825',
  meesho:   '#9C27B0',
  snapdeal: '#E53935',
  amazon:   '#FF9900',
}

const VIEWS = ['statement', 'overview', 'pnl', 'ops', 'insights']

/**
 * Generic top-level route for /pnl/:platform/:reportId.
 * Platform-aware: reads `platform` from URL params, passes it to children.
 * Replaces the old FlipkartReport.jsx (which was hardcoded to Flipkart).
 */
export default function PnLReport() {
  const { platform = 'flipkart', reportId } = useParams()
  const [searchParams, setSearchParams] = useSearchParams()
  const navigate                        = useNavigate()

  const platformName  = platform.charAt(0).toUpperCase() + platform.slice(1)
  const platformColor = PLATFORM_COLORS[platform.toLowerCase()] || '#888'

  const VIEW_LABELS = ['P&L Statement', `${platformName} Report`, 'Profit & Loss', 'Operating P&L', 'Insights']

  const view     = VIEWS.includes(searchParams.get('view')) ? searchParams.get('view') : VIEWS[0]
  const tabIndex = VIEWS.indexOf(view)

  const [report,  setReport]  = useState(null)
  const [loading, setLoading] = useState(true)
  const [error,   setError]   = useState(null)

  const fetchReport = useCallback((showLoader = true) => {
    if (showLoader) setLoading(true)
    setError(null)
    getPnlReport(Number(reportId))
      .then(data => { setReport(data); setLoading(false) })
      .catch(() => { setError('Report not found'); setLoading(false) })
  }, [reportId])

  useEffect(() => { fetchReport() }, [fetchReport])

  useEffect(() => {
    const onVisible = () => {
      if (document.visibilityState === 'visible') fetchReport(false)
    }
    document.addEventListener('visibilitychange', onVisible)
    return () => document.removeEventListener('visibilitychange', onVisible)
  }, [fetchReport])

  const { augmentedRows, insightsData } = useReportData(report)

  const setView = v => setSearchParams({ view: v }, { replace: true })

  if (loading) return (
    <div className="pnl-page"><div className="pnl-empty">Loading report…</div></div>
  )
  if (error) return (
    <div className="pnl-page">
      <div className="pnl-empty-state">
        <div className="pnl-empty-icon">⚠</div>
        <div className="pnl-empty-title">{error}</div>
        <button className="pnl-btn-ghost" onClick={() => navigate(`/pnl/${platform}`)}>← Back to Reports</button>
      </div>
    </div>
  )

  return (
    <div className="pnl-page">

      {/* ── Header ── */}
      <div className="pnl-header">
        <div className="pnl-title-row">
          <div>
            <div style={{ display: 'flex', alignItems: 'center', gap: 8, marginBottom: 6 }}>
              <button className="pnl-btn-ghost" style={{ fontSize: 11, padding: '3px 10px' }}
                onClick={() => navigate(`/pnl/${platform}`)}>← Reports</button>
              <div className="pnl-platform-badge">
                <span className="pnl-fk-dot" style={{ background: platformColor }} />
                {platformName}
              </div>
            </div>
            <h1 className="pnl-title">{fmtPeriod(report.period_start, report.period_end)}</h1>
            <div style={{ fontSize: 11, color: 'var(--text-3)', marginTop: 2 }}>{report.filename}</div>
          </div>
          <button
            className="pnl-btn-ghost"
            style={{ fontSize: 11, padding: '4px 12px', alignSelf: 'flex-start' }}
            onClick={() => fetchReport(false)}
            title="Refetch live pricing from Casper">
            ↻ Refresh
          </button>
        </div>
        <div className="pnl-tabs">
          {VIEW_LABELS.map((label, i) => (
            <button key={label} className={`pnl-tab${tabIndex === i ? ' active' : ''}`}
              onClick={() => setView(VIEWS[i])}>{label}</button>
          ))}
        </div>
      </div>

      {view === 'statement' && <IncomeStatement report={report} />}
      {view === 'overview'  && <ReportOverview  report={report} insightsData={insightsData} platform={platform} onViewPnL={() => setView('pnl')} />}
      {view === 'pnl'       && <ProfitLossView   report={report} augmentedRows={augmentedRows} platform={platform} />}
      {view === 'ops'       && <OperatingPnLView report={report} onRefresh={() => fetchReport(false)} />}
      {view === 'insights'  && <InsightsPanel    report={report} insightsData={insightsData} />}

    </div>
  )
}

import { useState, useEffect } from 'react'
import { getPnlStatement, getPnlTrend } from '../../../api/client'
import { fmt } from './utils'

/**
 * P&L Statement — industry-standard contribution-margin income statement.
 * All math comes from the backend engine (/pnl/statement/{id}); this view only
 * presents it: statement lines with margin tiers, settlement reconciliation,
 * COGS-coverage data-quality, a period-over-period trend, and CSV/print export.
 */

// Which subtotal lines carry a margin % (of net sales).
const MARGIN_FOR = {
  net_sales:        'net_sales_100',
  gross_profit:     'gross_margin_pct',
  contribution:     'contribution_margin_pct',
  operating_profit: 'operating_margin_pct',
}

function money(v) {
  if (v == null) return '—'
  const neg = v < 0
  const s = fmt(Math.abs(v))
  return neg ? `(${s})` : s
}

export default function IncomeStatement({ report }) {
  const [stmt, setStmt]       = useState(null)
  const [trend, setTrend]     = useState(null)
  const [loading, setLoading] = useState(true)
  const [err, setErr]         = useState(null)

  useEffect(() => {
    let alive = true
    setLoading(true); setErr(null)
    getPnlStatement(report.id)
      .then(s => { if (alive) { setStmt(s); setLoading(false) } })
      .catch(() => { if (alive) { setErr('Could not build statement'); setLoading(false) } })
    getPnlTrend(report.platform_id).then(t => alive && setTrend(t)).catch(() => {})
    return () => { alive = false }
  }, [report.id, report.platform_id])

  if (loading) return <div className="pnl-body"><div className="pnl-empty">Building statement…</div></div>
  if (err || !stmt) return <div className="pnl-body"><div className="pnl-empty">{err || 'No statement data'}</div></div>

  const st = stmt.subtotals, m = stmt.margins, rec = stmt.reconciliation, cov = stmt.coverage
  const reconciled = Math.abs(rec.variance || 0) < 1
  const profitTone = (st.operating_profit || 0) >= 0 ? 'pos' : 'neg'

  return (
    <div className="pnl-body pnl-body-full pnl-animate-in">

      {/* KPI header */}
      <div className="is-kpis">
        <Kpi label="Net Sales"        value={fmt(st.net_sales)} />
        <Kpi label="Net Payout"       value={fmt(st.net_payout)} sub={reconciled ? 'Reconciled' : 'Check settlement'} subTone={reconciled ? 'pos' : 'amber'} />
        <Kpi label="Operating Profit" value={fmt(st.operating_profit)} tone={profitTone} big />
        <Kpi label="Operating Margin" value={m.operating_margin_pct != null ? m.operating_margin_pct + '%' : '—'} tone={profitTone} />
        <Kpi label="Platform Take"    value={m.take_rate_pct != null ? m.take_rate_pct + '%' : '—'} tone="muted" />
        <div className="is-actions">
          <button className="pnl-btn-ghost" onClick={() => exportCsv(stmt)}>Export CSV</button>
          <button className="pnl-btn-ghost" onClick={() => window.print()}>Print</button>
        </div>
      </div>

      {cov.cost_basis === 'estimated' && (
        <div className="is-warn">
          Costs are <strong>estimated</strong> from today's SKU pricing — this report was uploaded
          before cost snapshots existed, so its profit can shift if you edit pricing. Re-upload it
          to freeze the cost basis.
        </div>
      )}

      {!cov.reliable && cov.cogs_coverage_pct != null && (
        <div className="is-warn">
          COGS coverage {cov.cogs_coverage_pct}% — {cov.total_units - cov.matched_units} of {cov.total_units} units
          have no cost match, so profit is understated. Add pricing in SKUs to complete the statement.
        </div>
      )}

      <div className="is-grid">
        {/* The statement */}
        <div className="is-statement" id="income-statement-print">
          <div className="is-hdr">
            <span>{stmt.report.platform} · {stmt.report.period}</span>
            <span className="is-hdr-amt">Amount</span>
            <span className="is-hdr-margin">% Net Sales</span>
          </div>
          {stmt.lines.map(l => {
            const mKey = MARGIN_FOR[l.key]
            const marginPct = mKey === 'net_sales_100' ? 100 : (mKey ? m[mKey] : null)
            return <StatementLine key={l.key} line={l} marginPct={marginPct} />
          })}
        </div>

        {/* Reconciliation + trend */}
        <div className="is-side">
          <div className={`is-recon ${reconciled ? 'ok' : 'warn'}`}>
            <div className="is-recon-title">Settlement Reconciliation</div>
            <div className="is-recon-row"><span>Computed net payout</span><span>{fmt(rec.computed_net_payout)}</span></div>
            <div className="is-recon-row"><span>Actual bank settlement</span><span>{fmt(rec.actual_bank_settlement)}</span></div>
            <div className="is-recon-row strong"><span>Variance</span><span>{fmt(rec.variance)}</span></div>
            <div className="is-recon-badge">{reconciled ? 'Statement reconciles to platform settlement' : 'Does not fully reconcile — review fees'}</div>
          </div>
          <TrendCard trend={trend} />
        </div>
      </div>
    </div>
  )
}

function Kpi({ label, value, sub, subTone, tone = '', big }) {
  return (
    <div className={`is-kpi${big ? ' big' : ''}`}>
      <div className="is-kpi-label">{label}</div>
      <div className={`is-kpi-val ${tone}`}>{value}</div>
      {sub && <div className={`is-kpi-sub ${subTone || ''}`}>{sub}</div>}
    </div>
  )
}

function StatementLine({ line, marginPct }) {
  const neg = (line.amount || 0) < 0
  const cls = line.kind === 'total' ? 'total' : line.kind === 'subtotal' ? 'subtotal' : line.kind === 'revenue' ? 'revenue' : 'expense'
  return (
    <div className={`is-line ${cls}`} style={{ paddingLeft: 16 + line.depth * 18 }}>
      <span className="is-line-label">
        {line.label}
        {line.note && <span className="is-line-note">{line.note}</span>}
      </span>
      <span className={`is-line-amt ${neg ? 'neg' : ''}`}>{money(line.amount)}</span>
      <span className="is-line-margin">{marginPct != null ? `${marginPct}%` : ''}</span>
    </div>
  )
}

function TrendCard({ trend }) {
  if (!trend || !trend.series || trend.series.length < 2) {
    return (
      <div className="is-trend">
        <div className="is-recon-title">Profit Trend</div>
        <div className="is-trend-empty">Upload more periods to see a month-over-month trend.</div>
      </div>
    )
  }
  const series = trend.series
  const max = Math.max(...series.map(s => Math.abs(s.operating_profit || 0)), 1)
  const d = trend.delta
  return (
    <div className="is-trend">
      <div className="is-recon-title">Operating Profit Trend</div>
      <div className="is-trend-bars">
        {series.map((s, i) => {
          const h = Math.round((Math.abs(s.operating_profit || 0) / max) * 100)
          const neg = (s.operating_profit || 0) < 0
          return (
            <div key={i} className="is-trend-bar-wrap" title={`${s.period}: ${fmt(s.operating_profit)}`}>
              <div className={`is-trend-bar ${neg ? 'neg' : ''}`} style={{ height: `${Math.max(h, 3)}%` }} />
              <div className="is-trend-lbl">{(s.period || '').slice(5)}</div>
            </div>
          )
        })}
      </div>
      {d && (
        <div className="is-trend-delta">
          <span>vs previous</span>
          <span className={(d.operating_profit || 0) >= 0 ? 'pos' : 'neg'}>
            {(d.operating_profit || 0) >= 0 ? '+' : ''}{fmt(d.operating_profit)}
            {d.operating_margin_pct != null && <> · {(d.operating_margin_pct >= 0 ? '+' : '')}{d.operating_margin_pct}pp</>}
          </span>
        </div>
      )}
    </div>
  )
}

// ── CSV export ───────────────────────────────────────────────────────────────
function exportCsv(stmt) {
  const rows = [['Line', 'Amount (INR)']]
  stmt.lines.forEach(l => rows.push([l.label, l.amount ?? 0]))
  rows.push([])
  rows.push(['Gross margin %', stmt.margins.gross_margin_pct ?? ''])
  rows.push(['Contribution margin %', stmt.margins.contribution_margin_pct ?? ''])
  rows.push(['Operating margin %', stmt.margins.operating_margin_pct ?? ''])
  rows.push(['Platform take %', stmt.margins.take_rate_pct ?? ''])
  const csv = rows.map(r => r.map(c => `"${String(c).replace(/"/g, '""')}"`).join(',')).join('\n')
  const blob = new Blob([csv], { type: 'text/csv;charset=utf-8;' })
  const url = URL.createObjectURL(blob)
  const a = document.createElement('a')
  a.href = url
  a.download = `pnl-statement-${stmt.report.platform}-${stmt.report.period}.csv`
  a.click()
  URL.revokeObjectURL(url)
}

import { useState } from 'react'
import { fmt, fmtN } from './utils'
import { Check, XMark } from './glyphs'
import { useOperatingPnlData }    from './useOperatingPnlData'
import OperatingPnlPatternCards   from './OperatingPnlPatternCards'
import { updatePlatform }    from '../../../api/client'

/**
 * Operating P&L tab — full-business profitability including overhead absorption.
 *
 * Answers: "Did the business actually make money this month, after ALL costs?"
 *
 *   Total Payout  = Flipkart Bank Settlement (cash received)
 *   Total Cost    = breakeven × units (incl. misc/rent/elec allocation)
 *   Net Profit    = Total Payout − Total Cost − Overhead Drag (un-recovered fixed cost)
 *   Net Margin %  = Net Profit / Total Cost × 100  (return on cost — same as Unit Economics)
 *
 * Overhead Drag = (target_units − delivered_units) × misc_per_unit  (only if positive)
 *   Surfaces the hidden loss from under-selling vs target volume.
 */
export default function OperatingPnLView({ report, onRefresh }) {
  const { totals, killList, returnLeakage, dataGap } = useOperatingPnlData(report)

  return (
    <div className="pnl-body pnl-body-full pnl-animate-in">

      {/* ── Verdict banner (red if losing, green if profiting) ─────────────── */}
      <VerdictBanner totals={totals} />

      {/* ── KPI strip ──────────────────────────────────────────────────────── */}
      <div className="pnl-summary-bar">
        <SumItem label="Total Payout" value={fmt(totals.payout)} valClass="gold" />
        <SumItem label="Total Cost"   value={fmt(totals.total_cost)} valClass="red" />
        <SumItem label="Total Cost (after GST)" value={fmt(totals.total_cost_gst)} valClass="muted" />
        <div className="pnl-sum-item">
          <div className="pnl-sum-label">Net Profit</div>
          <div className={`pnl-sum-val ${totals.net_profit >= 0 ? 'green' : 'red'}`}>
            {totals.net_profit >= 0 ? '+' : ''}{fmt(totals.net_profit)}
          </div>
        </div>
        <div className="pnl-sum-item">
          <div className="pnl-sum-label">Net Margin</div>
          <div className={`pnl-sum-val ${(totals.net_margin ?? 0) >= 0 ? 'green' : 'red'}`}>
            {totals.net_margin == null ? '—' : (totals.net_margin >= 0 ? '+' : '') + totals.net_margin.toFixed(1) + '%'}
          </div>
        </div>
        <div className="pnl-sum-item">
          <div className="pnl-sum-label">Net Margin (after GST)</div>
          <div className={`pnl-sum-val ${(totals.net_margin_gst ?? 0) >= 0 ? 'green' : 'red'}`}>
            {totals.net_margin_gst == null ? '—' : (totals.net_margin_gst >= 0 ? '+' : '') + totals.net_margin_gst.toFixed(1) + '%'}
          </div>
        </div>
        <div className="pnl-sum-divider"/>
        <div className="pnl-sum-item">
          <div className="pnl-sum-label">Overhead Drag</div>
          <div className="pnl-sum-val red">
            {totals.overhead_drag > 0 ? '-' + fmt(totals.overhead_drag) : fmt(0)}
          </div>
        </div>
        <div className="pnl-sum-item">
          <div className="pnl-sum-label">Final Profit</div>
          <div className={`pnl-sum-val ${totals.final_profit >= 0 ? 'green' : 'red'}`}>
            {totals.final_profit >= 0 ? '+' : ''}{fmt(totals.final_profit)}
          </div>
        </div>
        <div className="pnl-sum-item">
          <div className="pnl-sum-label">Final Margin</div>
          <div className={`pnl-sum-val ${(totals.final_margin ?? 0) >= 0 ? 'green' : 'red'}`}>
            {totals.final_margin == null ? '—' : (totals.final_margin >= 0 ? '+' : '') + totals.final_margin.toFixed(1) + '%'}
          </div>
        </div>
        <div className="pnl-sum-divider"/>
        <SumItem label="Total Units" value={fmtN(totals.total_units)} />
        <TargetUnitsEditor
          platformId={report.platform_id}
          initial={totals.target_units}
          volumePct={totals.volume_pct}
          onSaved={onRefresh}
        />
        <div className="pnl-sum-divider"/>
        <SumItem label="Kill List" value={totals.kill_count} valClass={totals.kill_count > 0 ? 'red' : ''} />
        <SumItem label="Data Gap" value={totals.gap_count} valClass={totals.gap_count > 0 ? 'amber' : ''} />
      </div>

      {/* ── Pattern cards ──────────────────────────────────────────────────── */}
      <OperatingPnlPatternCards
        killList={killList}
        returnLeakage={returnLeakage}
        dataGap={dataGap}
        totals={totals}
      />

      {/* Operating P&L is now a dashboard view — for per-SKU detail, see Profit & Loss tab */}
      <div className="pnl-ops-hint">
        Need per-SKU detail? See the <strong>Profit & Loss</strong> tab.
      </div>

    </div>
  )
}

// ── Sub-components ──────────────────────────────────────────────────────────

function VerdictBanner({ totals }) {
  if (totals.final_profit == null || totals.payout === 0) return null
  const losing = totals.final_profit < 0
  return (
    <div className={`pnl-verdict-banner ${losing ? 'losing' : 'winning'}`}>
      <span className={`pnl-verdict-dot ${losing ? 'loss' : 'ok'}`} />
      <span>
        You received <strong>{fmt(totals.payout)}</strong> from Flipkart but spent{' '}
        <strong>{fmt(totals.total_cost)}</strong> on these products
        {totals.overhead_drag > 0 && <> and under-absorbed <strong>{fmt(totals.overhead_drag)}</strong> of fixed costs</>}.
        {' '}
        Final {losing ? 'loss' : 'profit'}:{' '}
        <strong>{losing ? '' : '+'}{fmt(totals.final_profit)}</strong>
        {totals.final_margin != null && <> ({totals.final_margin >= 0 ? '+' : ''}{totals.final_margin.toFixed(1)}%)</>}
      </span>
    </div>
  )
}

function TargetUnitsEditor({ platformId, initial, volumePct, onSaved }) {
  const [editing, setEditing] = useState(false)
  const [value,   setValue]   = useState(initial || 700)
  const [saving,  setSaving]  = useState(false)

  async function save() {
    setSaving(true)
    try {
      await updatePlatform(platformId, { target_monthly_units: Number(value) })
      setEditing(false)
      onSaved?.()
    } catch (e) { console.error(e) }
    setSaving(false)
  }

  return (
    <div className="pnl-sum-item" title="Click to edit your monthly volume target">
      <div className="pnl-sum-label">Target / Actual</div>
      {editing ? (
        <div style={{ display: 'flex', gap: 4, alignItems: 'center' }}>
          <input type="number" value={value} onChange={e => setValue(e.target.value)}
            style={{ width: 60, fontSize: 12, padding: '2px 4px' }} />
          <button className="pnl-btn-ghost" style={{ display: 'inline-flex', alignItems: 'center', padding: '3px 6px' }}
            onClick={save} disabled={saving} aria-label="Save target">{saving ? '…' : <Check s={13} />}</button>
          <button className="pnl-btn-ghost" style={{ display: 'inline-flex', alignItems: 'center', padding: '3px 6px' }}
            onClick={() => setEditing(false)} aria-label="Cancel">{<XMark s={13} />}</button>
        </div>
      ) : (
        <div className="pnl-sum-val" style={{ cursor: 'pointer' }} onClick={() => setEditing(true)}>
          {initial || '—'}
          {volumePct != null && <span className={`pnl-sum-pct ${volumePct >= 100 ? 'green' : 'amber'}`}> ({volumePct.toFixed(0)}%)</span>}
        </div>
      )}
    </div>
  )
}

function SumItem({ label, value, valClass = '' }) {
  return (
    <div className="pnl-sum-item">
      <div className="pnl-sum-label">{label}</div>
      <div className={`pnl-sum-val ${valClass}`}>{value}</div>
    </div>
  )
}

import { fmt, fmtN, fmtPct } from './utils'
import { Ban, Warn, Search, TrendDown } from './glyphs'

/**
 * Four pattern-detection cards surfaced on the Operating P&L view:
 *   1. Kill List           — SKUs selling below cost
 *   2. Return Leakage      — SKUs with >30% return rate
 *   3. Data Gap            — FK SKUs not in Casper master (can't compute P&L)
 *   4. Volume Absorption   — fixed-cost recovery vs target
 */
export default function OperatingPnlPatternCards({ killList, returnLeakage, dataGap, totals }) {
  return (
    <div className="pnl-pattern-grid">

      {/* Kill List */}
      <Card
        icon={<Ban />}
        title="Kill List"
        subtitle="BS/unit < breakeven"
        count={killList.length}
        countClass="red"
        empty="All matched SKUs sell above cost — no hard losers."
        emptyGood
      >
        {killList.slice(0, 5).map(r => (
          <PatternRow key={r.id}
            name={r.platform_sku_name}
            meta={`${fmtN(r.net_units)}u · BS/u ${fmt(r.true_bs_per_u, 1)}`}
            right={<span className="pnl-pattern-val red">-{fmt(-r.true_profit_u, 1)}/u</span>}
          />
        ))}
        {killList.length > 5 && <div className="pnl-pattern-more">+ {killList.length - 5} more</div>}
      </Card>

      {/* Return Leakage */}
      <Card
        icon={<Warn />}
        title="Return Leakage"
        subtitle="Return rate > 30%"
        count={returnLeakage.length}
        countClass="amber"
        empty="No SKUs in high-return zone."
        emptyGood
      >
        {returnLeakage.slice(0, 5).map(r => (
          <PatternRow key={r.id}
            name={r.platform_sku_name}
            meta={`${fmtN(r.gross_units)} gross → ${fmtN(r.net_units)} net`}
            right={<span className="pnl-pattern-val amber">{fmtPct(r.true_return_pct)}</span>}
          />
        ))}
        {returnLeakage.length > 5 && <div className="pnl-pattern-more">+ {returnLeakage.length - 5} more</div>}
      </Card>

      {/* Data Gap */}
      <Card
        icon={<Search />}
        title="Data Gap"
        subtitle="Unmatched Flipkart SKUs"
        count={dataGap.length}
        countClass="amber"
        empty="All Flipkart SKUs matched to Casper master."
        emptyGood
      >
        {dataGap.slice(0, 5).map(r => (
          <PatternRow key={r.id}
            name={r.platform_sku_name}
            meta={`${fmtN(r.gross_units || 0)} gross · ${fmtN(r.net_units || 0)} net`}
            right={<span className="pnl-pattern-val muted">{fmt(r.bank_settlement_projected || 0)}</span>}
          />
        ))}
        {dataGap.length > 5 && <div className="pnl-pattern-more">+ {dataGap.length - 5} more</div>}
        {dataGap.length > 0 && (
          <div className="pnl-pattern-hint">Add these to SKUs → Pricing to include in Operating P&L.</div>
        )}
      </Card>

      {/* Volume Absorption */}
      <Card
        icon={<TrendDown />}
        title="Volume Absorption"
        subtitle="Fixed-cost recovery"
        badge={totals.target_units > 0 && totals.volume_pct != null ? `${totals.volume_pct.toFixed(0)}%` : null}
        badgeClass={totals.volume_pct != null && totals.volume_pct >= 100 ? 'green' : 'amber'}
      >
        <div className="pnl-absorp-stat">
          <span className="pnl-absorp-label">Target</span>
          <span className="pnl-absorp-val">{fmtN(totals.target_units)} units</span>
        </div>
        <div className="pnl-absorp-stat">
          <span className="pnl-absorp-label">Delivered</span>
          <span className="pnl-absorp-val">{fmtN(totals.net_units)} units</span>
        </div>
        <div className="pnl-absorp-stat">
          <span className="pnl-absorp-label">Misc / unit</span>
          <span className="pnl-absorp-val">{fmt(totals.misc_per_unit, 2)}</span>
        </div>
        <div className="pnl-absorp-stat">
          <span className="pnl-absorp-label">Overhead budget</span>
          <span className="pnl-absorp-val">{fmt(totals.target_absorp)}</span>
        </div>
        <div className="pnl-absorp-stat">
          <span className="pnl-absorp-label">Recovered</span>
          <span className="pnl-absorp-val green">{fmt(totals.actual_absorp)}</span>
        </div>
        <div className="pnl-absorp-stat strong">
          <span className="pnl-absorp-label">
            {totals.absorption_gap >= 0 ? 'Under-absorbed' : 'Over-absorbed'}
          </span>
          <span className={`pnl-absorp-val ${totals.absorption_gap > 0 ? 'red' : 'green'}`}>
            {totals.absorption_gap >= 0 ? '-' : '+'}{fmt(Math.abs(totals.absorption_gap))}
          </span>
        </div>
      </Card>

    </div>
  )
}

function Card({ icon, title, subtitle, count, countClass, badge, badgeClass, empty, emptyGood, children }) {
  const isEmpty = !children || (Array.isArray(children) && children.every(c => !c))
  const hasList = count != null
  return (
    <div className="pnl-pattern-card">
      <div className="pnl-pattern-head">
        <span className="pnl-pattern-icon">{icon}</span>
        <div className="pnl-pattern-titles">
          <div className="pnl-pattern-title">{title}</div>
          <div className="pnl-pattern-sub">{subtitle}</div>
        </div>
        {hasList && <span className={`pnl-pattern-count ${countClass || ''}`}>{count}</span>}
        {badge && <span className={`pnl-pattern-count ${badgeClass || ''}`}>{badge}</span>}
      </div>
      <div className="pnl-pattern-body">
        {hasList && count === 0
          ? <div className={`pnl-pattern-empty ${emptyGood ? 'good' : ''}`}>{empty}</div>
          : children}
      </div>
    </div>
  )
}

function PatternRow({ name, meta, right }) {
  return (
    <div className="pnl-pattern-row">
      <div className="pnl-pattern-row-left">
        <div className="pnl-pattern-row-name">{name}</div>
        <div className="pnl-pattern-row-meta">{meta}</div>
      </div>
      <div className="pnl-pattern-row-right">{right}</div>
    </div>
  )
}

import { useState, useEffect, useRef } from 'react'
import { useNavigate } from 'react-router-dom'
import { fmt, fmtN, fmtPct } from './utils'
import { getPnlRows, getUnmatchedSkus, addHiddenSkuPricing, getVendors, getCategories, errText } from '../../../api/client'

/**
 * Profit & Loss tab — per-SKU actual-vs-target reconciliation.
 * ALL math comes from the backend engine (GET /pnl/rows/{id}) — single source of
 * truth. Every computed number carries a `calc` breakdown so hovering it shows the
 * exact formula + underlying values.
 */

function fmtOp(v, kind) {
  if (v == null) return ''
  return kind === 'n' ? fmtN(v) : fmt(v)
}
function fmtRes(calc) {
  if (calc.result == null) return '—'
  return calc.unit === 'pct'
    ? (calc.result >= 0 ? '+' : '') + calc.result.toFixed(1) + '%'
    : fmt(calc.result)
}

// Hover-to-explain cell. Fixed-position popover (the table scrolls, so an
// absolutely-positioned one would be clipped by the overflow container).
function Calc({ value, title, calc }) {
  const [pos, setPos] = useState(null)
  const ref = useRef(null)
  if (!calc) return value
  const show = () => { const r = ref.current?.getBoundingClientRect(); if (r) setPos({ x: r.left + r.width / 2, y: r.top }) }
  return (
    <span ref={ref} className="calc-cell" onMouseEnter={show} onMouseLeave={() => setPos(null)}>
      {value}
      {pos && (
        <span className="calc-pop" style={{ left: pos.x, top: pos.y }}>
          <span className="calc-pop-title">{title}</span>
          {calc.ops.map(([label, val, kind], i) => (
            <span key={i} className="calc-pop-row"><span className="cl">{label}</span><span className="cv">{fmtOp(val, kind)}</span></span>
          ))}
          <span className="calc-pop-row calc-pop-result"><span className="cl">Result</span><span className="cv">{fmtRes(calc)}</span></span>
        </span>
      )}
    </span>
  )
}

const CALC_TITLES = {
  return_rate_pct: 'Return Rate', casper_breakeven: 'Breakeven / unit',
  fees_per_unit: 'Platform Fee / unit', total_earned: 'Net Payout',
  fk_bs_per_unit: 'Payout / unit', profit_no_gst: 'Profit / unit',
  expected_total: 'Total Cost', total_true_profit: 'Net Profit',
  real_margin_pct: 'Net Margin', margin_gst_pct: 'Net Margin (after GST)',
}
// Wrap a cell's value with its backend calc breakdown (hover to explain).
function C({ row, k, children }) {
  return <Calc value={children} title={CALC_TITLES[k]} calc={row.calc?.[k]} />
}

/**
 * Hidden-SKU panel — the SKUs in this report that have no cost in the master, so
 * they are excluded from profit. Entering a price creates the pricing, registers
 * the upload's name as the platform alias, and re-matches this report in one call,
 * so the numbers move immediately instead of needing a re-upload.
 */
const BLANK_COSTS = {
  price: '', package: '', logistics: '', addons: '', misc_total: '',
  cr_percentage: '', cr_cost: '', damage_percentage: '', damage_cost: '',
  vendor_id: '', category_id: '',
}

// Same cost stack as the SKUs grid. Blank = fall back to the company default,
// which the backend resolves — so only Price is truly required.
const COST_FIELDS = [
  { key: 'package',           label: 'Package' },
  { key: 'logistics',         label: 'Logistics' },
  { key: 'addons',            label: 'Addons' },
  { key: 'misc_total',        label: 'Misc', hint: 'default' },
  { key: 'cr_percentage',     label: 'Return %', pairs: 'cr_cost' },
  { key: 'cr_cost',           label: 'Return ₹', pairs: 'cr_percentage' },
  { key: 'damage_percentage', label: 'Dmg %',    pairs: 'damage_cost' },
  { key: 'damage_cost',       label: 'Dmg ₹',    pairs: 'damage_percentage' },
]

function HiddenSkuPanel({ reportId, onClose, onMatched }) {
  const [items, setItems]   = useState(null)
  const [openSku, setOpen]  = useState(null)
  const [form, setForm]     = useState(BLANK_COSTS)
  const [vendors, setVendors] = useState([])
  const [categories, setCategories] = useState([])
  const [busy, setBusy]     = useState(false)
  const [err, setErr]       = useState('')

  useEffect(() => {
    getUnmatchedSkus(reportId).then(setItems).catch(() => setItems([]))
    getVendors().then(setVendors).catch(() => setVendors([]))
    // Asked for here so SKUs added this way arrive categorised — adding them
    // without a category is what left 71 of 72 SKUs uncategorised.
    getCategories().then(setCategories).catch(() => setCategories([]))
  }, [reportId])

  // % and ₹ are two ways to say the same thing — entering one clears its partner
  // so the backend never receives a contradictory pair.
  const setField = (key, value, pairs) =>
    setForm(f => ({ ...f, [key]: value, ...(pairs ? { [pairs]: '' } : {}) }))

  // Live preview of what this SKU will cost you per unit.
  const previewBreakeven = (() => {
    const n = k => parseFloat(form[k]) || 0
    const base = n('price') + n('package') + n('logistics') + n('addons') + n('misc_total')
    return base > 0 ? base + n('cr_cost') + n('damage_cost') : null
  })()

  const submit = async (name) => {
    if (!form.price || Number(form.price) <= 0) { setErr('Enter a price greater than 0'); return }
    setBusy(true); setErr('')
    try {
      const payload = { platform_sku_name: name, report_id: reportId }
      Object.entries(form).forEach(([k, v]) => { if (v !== '') payload[k] = v })
      const r = await addHiddenSkuPricing(payload)
      setItems(p => p.filter(x => x.platform_sku_name !== name))
      setOpen(null); setForm(BLANK_COSTS)
      onMatched(r)
    } catch (e) {
      setErr(errText(e, 'Could not add SKU'))
    } finally { setBusy(false) }
  }

  return (
    <div className="hs-overlay" onClick={onClose}>
      <aside className="hs-panel" onClick={e => e.stopPropagation()}>
        <header className="hs-head">
          <div>
            <div className="hs-title">SKUs with no cost data</div>
            <div className="hs-sub">
              Their sales are excluded from profit until you add a cost. Biggest first.
            </div>
          </div>
          <button className="hs-close" onClick={onClose} aria-label="Close">×</button>
        </header>

        {items === null && <div className="hs-empty">Loading…</div>}
        {items?.length === 0 && <div className="hs-empty">Nothing hidden — every SKU has a cost.</div>}

        <div className="hs-list">
          {items?.map(u => (
            <div key={u.platform_sku_name} className="hs-item">
              <div className="hs-item-row">
                <span className="hs-name">{u.platform_sku_name}</span>
                <span className="hs-meta">{u.units} units · {fmt(u.payout)}</span>
                <button className="btn btn-ghost btn-sm"
                  onClick={() => { setOpen(openSku === u.platform_sku_name ? null : u.platform_sku_name); setForm(BLANK_COSTS); setErr('') }}>
                  {openSku === u.platform_sku_name ? 'Cancel' : 'Add cost'}
                </button>
              </div>
              {openSku === u.platform_sku_name && (
                <div className="hs-form">
                  <div className="hs-grid">
                    <label className="hs-f">Vendor
                      <select value={form.vendor_id} onChange={e => setField('vendor_id', e.target.value)}>
                        <option value="">— none —</option>
                        {vendors.map(v => <option key={v.id} value={v.id}>{v.name}</option>)}
                      </select>
                    </label>
                    <label className="hs-f">Category
                      <select value={form.category_id} onChange={e => setField('category_id', e.target.value)}>
                        <option value="">— none —</option>
                        {categories.map(c => <option key={c.id} value={c.id}>{c.name}</option>)}
                      </select>
                    </label>
                    <label className="hs-f hs-f-req">Price ₹
                      <input type="number" min="0" step="0.01" autoFocus value={form.price}
                        placeholder="required"
                        onChange={e => setField('price', e.target.value)}
                        onKeyDown={e => e.key === 'Enter' && submit(u.platform_sku_name)} />
                    </label>
                    {COST_FIELDS.map(f => (
                      <label key={f.key} className="hs-f">{f.label}
                        <input type="number" min="0" step="0.01" value={form[f.key]}
                          placeholder={f.hint || 'auto'}
                          onChange={e => setField(f.key, e.target.value, f.pairs)}
                          onKeyDown={e => e.key === 'Enter' && submit(u.platform_sku_name)} />
                      </label>
                    ))}
                  </div>

                  <div className="hs-actions">
                    <span className="hs-preview">
                      {previewBreakeven
                        ? <>Breakeven <strong>{fmt(previewBreakeven)}</strong> / unit</>
                        : 'Enter a price to see breakeven'}
                    </span>
                    <button className="btn btn-accent btn-sm" disabled={busy}
                      onClick={() => submit(u.platform_sku_name)}>
                      {busy ? 'Saving…' : 'Save & match'}
                    </button>
                  </div>
                  <p className="hs-hint">
                    Blank fields use your company defaults. Return and Damage each accept a %
                    <em>or</em> a ₹ amount — filling one clears the other.
                  </p>
                  {err && <p className="hs-err">{err}</p>}
                </div>
              )}
            </div>
          ))}
        </div>
      </aside>
    </div>
  )
}

export default function ProfitLossView({ report, platform = 'flipkart' }) {
  const platformName = platform.charAt(0).toUpperCase() + platform.slice(1)
  const navigate = useNavigate()
  const [data, setData]       = useState(null)   // { rows, summary }
  const [loading, setLoading] = useState(true)
  const [err, setErr]         = useState(null)
  const [skuFilter, setSkuFilter] = useState('all')
  const [skuSearch, setSkuSearch] = useState('')
  const [sortCol,   setSortCol]   = useState('total_true_profit')
  const [sortDir,   setSortDir]   = useState('asc')
  const [showHidden, setShowHidden] = useState(false)
  const [hiddenCount, setHiddenCount] = useState(report.unmatched_skus || 0)
  const [reloadKey, setReloadKey] = useState(0)

  useEffect(() => {
    let alive = true
    setLoading(true); setErr(null)
    getPnlRows(report.id)
      .then(d => { if (alive) { setData(d); setLoading(false) } })
      .catch(() => { if (alive) { setErr('Could not load P&L rows'); setLoading(false) } })
    return () => { alive = false }
  }, [report.id, reloadKey])

  // A SKU was costed and the report re-matched — pull the new numbers in.
  const onMatched = (r) => {
    setHiddenCount(r.remaining_hidden)
    setReloadKey(k => k + 1)
  }

  if (loading) return <div className="pnl-body"><div className="pnl-empty">Loading P&amp;L…</div></div>
  if (err || !data) return <div className="pnl-body"><div className="pnl-empty">{err || 'No data'}</div></div>

  const rows = data.rows
  const s = data.summary

  const filteredRows = rows
    .filter(r => {
      if (skuFilter === 'profit') return (r.total_true_profit ?? 0) > 0
      if (skuFilter === 'loss')   return (r.total_true_profit ?? 0) <= 0
      return true
    })
    .filter(r => !skuSearch || r.platform_sku_name.toLowerCase().includes(skuSearch.toLowerCase()))
    .sort((a, b) => {
      const av = a[sortCol] ?? (sortDir === 'asc' ? Infinity : -Infinity)
      const bv = b[sortCol] ?? (sortDir === 'asc' ? Infinity : -Infinity)
      return sortDir === 'asc' ? av - bv : bv - av
    })

  function toggleSort(col) {
    if (sortCol === col) setSortDir(d => d === 'asc' ? 'desc' : 'asc')
    else { setSortCol(col); setSortDir('asc') }
  }

  const pct = v => v == null ? '—' : (v >= 0 ? '+' : '') + v.toFixed(1) + '%'

  return (
    <div className="pnl-body pnl-body-full pnl-animate-in">

      {/* Summary bar (from backend) */}
      <div className="pnl-summary-bar">
        <SumItem label="Total Cost" valClass="muted" value={fmt(s.total_expected)} />
        <SumItem label="Total Payout" valClass="gold" value={fmt(s.total_actual)} />
        <div className="pnl-sum-item">
          <div className="pnl-sum-label">Net Profit</div>
          <div className={`pnl-sum-val ${(s.total_profit ?? 0) >= 0 ? 'green' : 'red'}`}>
            {(s.total_profit ?? 0) >= 0 ? '+' : ''}{fmt(s.total_profit)}
            {s.overall_var_pct != null && (
              <span className="pnl-sum-pct"> ({s.overall_var_pct >= 0 ? '+' : ''}{s.overall_var_pct.toFixed(1)}%)</span>
            )}
          </div>
        </div>
        <div className="pnl-sum-divider"/>
        <SumItem label="Avg Profit / unit" valClass={(s.avg_profit_per_unit ?? 0) >= 0 ? 'green' : 'red'}
          value={s.avg_profit_per_unit != null ? ((s.avg_profit_per_unit >= 0 ? '+' : '') + fmt(s.avg_profit_per_unit, 2)) : '—'} />
        <SumItem label="Net Margin" valClass={(s.weighted_margin_pct ?? 0) >= 0 ? 'green' : 'red'} value={pct(s.weighted_margin_pct)} />
        <SumItem label="Net Margin (after GST)" valClass={(s.weighted_margin_gst_pct ?? 0) >= 0 ? 'green' : 'red'} value={pct(s.weighted_margin_gst_pct)} />
        <div className="pnl-sum-divider"/>
        <SumItem label="Profitable" valClass="green" value={s.profitable} />
        <SumItem label="Loss-making" valClass="red"   value={s.loss_making} />
        <div className="pnl-sum-divider"/>
        <SumItem label="Total Units" value={fmtN(s.total_units)} />
        {hiddenCount > 0 && (
          <button className="pnl-sum-item pnl-sum-action" onClick={() => setShowHidden(true)}
            title="Add costs for these SKUs so they count towards profit">
            <div className="pnl-sum-label">No Pricing Data</div>
            <div className="pnl-sum-val amber">{hiddenCount} SKUs hidden <span className="pnl-sum-cta">Fix</span></div>
          </button>
        )}
      </div>

      {showHidden && (
        <HiddenSkuPanel reportId={report.id} onClose={() => setShowHidden(false)} onMatched={onMatched} />
      )}

      {/* Controls */}
      <div className="pnl-tbl-controls">
        <input className="pnl-search" placeholder="Search SKU…" value={skuSearch}
          onChange={e => setSkuSearch(e.target.value)} />
        <div className="pnl-filter-pills">
          {[
            { key: 'all',    label: `All (${rows.length})` },
            { key: 'profit', label: `Profitable (${s.profitable})` },
            { key: 'loss',   label: `Loss-making (${s.loss_making})` },
          ].map(f => (
            <button key={f.key} className={`pnl-fpill${skuFilter === f.key ? ' active' : ''}`}
              onClick={() => setSkuFilter(f.key)}>{f.label}</button>
          ))}
        </div>
        <span className="pnl-row-count">Hover any number to see its formula · {filteredRows.length} SKUs</span>
      </div>

      {/* Table */}
      <div className="pnl-tbl-wrap">
        <table className="pnl-tbl pnl-tbl-grouped">
          <thead>
            <tr className="pnl-gh-row">
              <th className="pnl-gh pnl-gh-sku sticky-col">SKU</th>
              <th className="pnl-gh pnl-gh-actual"  colSpan={3}>Sold</th>
              <th className="pnl-gh pnl-gh-bs"      colSpan={3}>Target</th>
              <th className="pnl-gh pnl-gh-ue"      colSpan={3}>Actual ({platformName})</th>
              <th className="pnl-gh pnl-gh-recon"   colSpan={6}>Variance / Bottom Line</th>
            </tr>
            <tr>
              <th className="pnl-th sticky-col"></th>
              <SortTh col="gross_units"            label="Gross Units"     sortCol={sortCol} sortDir={sortDir} onClick={toggleSort}/>
              <SortTh col="net_units"              label="Units Sold"      sub="after returns" sortCol={sortCol} sortDir={sortDir} onClick={toggleSort}/>
              <SortTh col="return_rate_pct"        label="Return Rate"     sortCol={sortCol} sortDir={sortDir} onClick={toggleSort}/>
              <SortTh col="casper_breakeven"       label="Breakeven"       sub="per unit · from SKU master" sortCol={sortCol} sortDir={sortDir} onClick={toggleSort}/>
              <SortTh col="casper_target_pre_gst"  label="Target Pre-GST"  sortCol={sortCol} sortDir={sortDir} onClick={toggleSort}/>
              <SortTh col="casper_target_post_gst" label="Target Post-GST" sortCol={sortCol} sortDir={sortDir} onClick={toggleSort}/>
              <SortTh col="fees_per_unit"          label="Platform Fee/u"  sub="commission + tax" sortCol={sortCol} sortDir={sortDir} onClick={toggleSort}/>
              <SortTh col="total_earned"           label="Net Payout"      sub="settled by platform" sortCol={sortCol} sortDir={sortDir} onClick={toggleSort}/>
              <SortTh col="fk_bs_per_unit"         label="Payout / unit"   sortCol={sortCol} sortDir={sortDir} onClick={toggleSort}/>
              <SortTh col="profit_no_gst"          label="Profit / unit"   sub="Payout − Breakeven" primary sortCol={sortCol} sortDir={sortDir} onClick={toggleSort}/>
              <SortTh col="expected_total"         label="Total Cost"      sub="Breakeven × Units" sortCol={sortCol} sortDir={sortDir} onClick={toggleSort}/>
              <SortTh col="total_true_profit"      label="Net Profit"      sub="Payout − Cost" primary sortCol={sortCol} sortDir={sortDir} onClick={toggleSort}/>
              <SortTh col="real_margin_pct"        label="Net Margin"      sub="Profit ÷ Cost" primary sortCol={sortCol} sortDir={sortDir} onClick={toggleSort}/>
              <SortTh col="margin_gst_pct"         label="Net Margin (after GST)" sub="GST-anchored" primary sortCol={sortCol} sortDir={sortDir} onClick={toggleSort}/>
              <th className="pnl-th center pnl-th-primary">Status</th>
            </tr>
          </thead>
          <tbody>
            {filteredRows.map(row => <PnLRow key={row.id} row={row} onJumpToSku={() => navigate(`/skus?sku=${encodeURIComponent(row.platform_sku_name)}`)} />)}
            {filteredRows.length === 0 && (
              <tr><td colSpan={16} className="pnl-td center" style={{ padding: '32px', color: 'var(--text-3)' }}>
                No SKUs match your filter
              </td></tr>
            )}
          </tbody>
        </table>
      </div>
    </div>
  )
}

// ── helpers ──────────────────────────────────────────────────────────────────

function SumItem({ label, value, valClass = '' }) {
  return (
    <div className="pnl-sum-item">
      <div className="pnl-sum-label">{label}</div>
      <div className={`pnl-sum-val ${valClass}`}>{value}</div>
    </div>
  )
}

function SortTh({ col, label, sub, primary, sortCol, sortDir, onClick }) {
  const icon = sortCol === col ? (sortDir === 'asc' ? ' ↑' : ' ↓') : ''
  return (
    <th className={`pnl-th sortable${primary ? ' pnl-th-primary' : ''}`} onClick={() => onClick(col)}>
      <span className="pnl-th-label">{label}</span>
      {sub && <span className="pnl-th-sub">{sub}</span>}
      {icon}
    </th>
  )
}

function PnLRow({ row, onJumpToSku }) {
  const profitNo = row.profit_no_gst
  const totalP   = row.total_true_profit
  const noCls    = profitNo == null ? '' : profitNo > 0 ? 'positive' : 'negative'
  const totalCls = totalP == null   ? '' : totalP > 0   ? 'positive' : 'negative'
  const isLoss   = profitNo != null && profitNo < 0
  const marginCls = v => v == null ? '' : v > 0 ? 'low' : v > -10 ? 'mid' : 'high'
  const marginTxt = v => (v >= 0 ? '+' : '') + v.toFixed(1) + '%'

  return (
    <tr className={`pnl-tr${isLoss ? ' pnl-tr-loss' : ''}`}>
      <td className="pnl-td sku-col sticky-col">
        <span className="pnl-sku-name">{row.platform_sku_name}</span>
        <button className="pnl-sku-link" title="View in SKUs page" aria-label="View in SKUs page" onClick={onJumpToSku}>
          <svg viewBox="0 0 16 16" width="12" height="12" fill="none" stroke="currentColor" strokeWidth="1.6" strokeLinecap="round" strokeLinejoin="round">
            <path d="M6 3H3.5A1.5 1.5 0 0 0 2 4.5v8A1.5 1.5 0 0 0 3.5 14h8A1.5 1.5 0 0 0 13 12.5V10"/><path d="M10 2h4v4"/><path d="M14 2 7 9"/>
          </svg>
        </button>
      </td>

      {/* Sold */}
      <td className="pnl-td center muted">{fmtN(row.gross_units)}</td>
      <td className="pnl-td center"><span className="pnl-units-net">{fmtN(row.net_units)}</span></td>
      <td className="pnl-td center">
        {row.return_rate_pct == null ? '—' : (
          <C row={row} k="return_rate_pct">
            <span className={`pnl-ret-rate ${row.return_rate_pct > 40 ? 'high' : row.return_rate_pct > 20 ? 'mid' : 'low'}`}>{fmtPct(row.return_rate_pct)}</span>
          </C>
        )}
      </td>

      {/* Target */}
      <td className="pnl-td right mono muted">
        {row.casper_breakeven == null ? '—' : <C row={row} k="casper_breakeven">{fmt(row.casper_breakeven, 1)}</C>}
      </td>
      <td className="pnl-td right mono muted">{row.casper_target_pre_gst != null ? fmt(row.casper_target_pre_gst, 0) : '—'}</td>
      <td className="pnl-td right mono muted">{row.casper_target_post_gst != null ? fmt(row.casper_target_post_gst, 0) : '—'}</td>

      {/* Actual */}
      <td className="pnl-td right mono red">
        {row.fees_per_unit == null ? '—' : <C row={row} k="fees_per_unit">{fmt(row.fees_per_unit, 1)}</C>}
      </td>
      <td className="pnl-td right mono">
        {row.total_earned == null ? '—' : <C row={row} k="total_earned">{fmt(row.total_earned)}</C>}
      </td>
      <td className="pnl-td right mono">
        {row.fk_bs_per_unit == null ? '—' : <C row={row} k="fk_bs_per_unit">{fmt(row.fk_bs_per_unit, 1)}</C>}
      </td>

      {/* Variance / Bottom Line */}
      <td className={`pnl-td right mono pnl-td-primary variance ${noCls}`}>
        {profitNo == null ? '—' : <C row={row} k="profit_no_gst">{(profitNo >= 0 ? '+' : '') + fmt(profitNo, 1)}</C>}
      </td>
      <td className="pnl-td right mono muted">
        {row.expected_total == null ? '—' : <C row={row} k="expected_total">{fmt(row.expected_total)}</C>}
      </td>
      <td className={`pnl-td right mono pnl-td-primary variance ${totalCls}`}>
        {totalP == null ? '—' : <C row={row} k="total_true_profit">{(totalP >= 0 ? '+' : '') + fmt(totalP)}</C>}
      </td>
      <td className="pnl-td center pnl-td-primary">
        {row.real_margin_pct == null ? '—' : (
          <C row={row} k="real_margin_pct">
            <span className={`pnl-ret-rate ${marginCls(row.real_margin_pct)}`}>{marginTxt(row.real_margin_pct)}</span>
          </C>
        )}
      </td>
      <td className="pnl-td center pnl-td-primary">
        {row.margin_gst_pct == null ? '—' : (
          <C row={row} k="margin_gst_pct">
            <span className={`pnl-ret-rate ${marginCls(row.margin_gst_pct)}`}>{marginTxt(row.margin_gst_pct)}</span>
          </C>
        )}
      </td>
      <td className="pnl-td center pnl-td-primary">
        <span className={`pnl-status-tag ${isLoss ? 'loss' : 'ok'}`}>
          <span className="pnl-status-dot" />{isLoss ? 'Loss' : 'OK'}
        </span>
      </td>
    </tr>
  )
}

import { useMemo } from 'react'

/**
 * Derives all computed fields for a Flipkart P&L report:
 *   - augmentedRows: matched SKU rows with per-unit cost/variance/margin fields
 *   - insightsData: aggregate totals + chart data for the Insights tab
 *
 * Kept as a hook (not a plain function) so memoization survives re-renders.
 */
export function useFlipkartData(report) {
  const augmentedRows = useMemo(() => {
    const matched = (report?.sku_rows || []).filter(r => r.is_matched)
    return matched.map(r => {
      const fkBsPerUnit = (r.bank_settlement_projected != null && r.net_units)
        ? r.bank_settlement_projected / r.net_units : null
      // Variance per unit now anchored on breakeven (not target BS)
      const varPerUnit = (fkBsPerUnit != null && r.casper_breakeven != null)
        ? fkBsPerUnit - r.casper_breakeven : null
      const varTotal = (varPerUnit != null && r.net_units != null)
        ? varPerUnit * r.net_units : null
      const feesPerUnit = r.net_units ? (
        (Math.abs(r.commission_fee || 0) + Math.abs(r.collection_fee || 0) +
         Math.abs(r.fixed_fee || 0) +
         Math.abs(r.taxes_gst || 0) + Math.abs(r.taxes_tcs || 0) + Math.abs(r.taxes_tds || 0)
         - Math.abs(r.rewards_benefits || 0)) / r.net_units
      ) : null
      const totalEarned   = r.bank_settlement_projected ?? null
      // Expected BS = breakeven × units (cash needed to recover cost, no profit)
      const expectedTotal = (r.casper_breakeven != null && r.net_units != null)
        ? r.casper_breakeven * r.net_units : null

      // Profit calcs use breakeven (cost-based, not target)
      const profitNoGst = (fkBsPerUnit != null && r.casper_breakeven != null)
        ? fkBsPerUnit - r.casper_breakeven : null
      const profitWithGst = (fkBsPerUnit != null && r.casper_breakeven_gst != null)
        ? fkBsPerUnit - r.casper_breakeven_gst : null
      // Margin % = return on cost (no GST): profit / breakeven × 100
      const realMarginPct = (fkBsPerUnit != null && r.casper_breakeven)
        ? ((fkBsPerUnit - r.casper_breakeven) / r.casper_breakeven) * 100 : null
      // Margin % including GST: profit_with_gst / breakeven_gst × 100
      const marginGstPct = (fkBsPerUnit != null && r.casper_breakeven_gst)
        ? ((fkBsPerUnit - r.casper_breakeven_gst) / r.casper_breakeven_gst) * 100 : null

      return {
        ...r,
        fk_bs_per_unit: fkBsPerUnit,
        true_profit_per_unit: varPerUnit,
        total_true_profit: varTotal,
        fees_per_unit: feesPerUnit,
        total_earned: totalEarned,
        expected_total: expectedTotal,
        profit_no_gst: profitNoGst,
        profit_with_gst: profitWithGst,
        real_margin_pct: realMarginPct,
        margin_gst_pct: marginGstPct,
      }
    })
  }, [report])

  const insightsData = useMemo(() => {
    if (!report) return null
    const rows    = report.sku_rows || []
    const matched = rows.filter(r => r.is_matched && r.variance_bs != null)
    const totalActualBS    = matched.reduce((s, r) => s + (r.bank_settlement_projected || 0), 0)
    const totalExpectedBS  = matched.reduce((s, r) => s + (r.casper_expected_bs || 0) * (r.net_units || 0), 0)
    const netVariance      = totalActualBS - totalExpectedBS
    const totalRevShipping = rows.reduce((s, r) => s + Math.abs(r.reverse_shipping_fee || 0), 0)
    const totalCommission  = rows.reduce((s, r) => s + Math.abs(r.commission_fee || 0), 0)
    const totalCollection  = rows.reduce((s, r) => s + Math.abs(r.collection_fee || 0), 0)
    const totalGST         = rows.reduce((s, r) => s + Math.abs(r.taxes_gst || 0), 0)
    const totalTax         = rows.reduce((s, r) => s + Math.abs(r.taxes_tcs || 0) + Math.abs(r.taxes_tds || 0), 0)
    const totalRewards     = rows.reduce((s, r) => s + (r.rewards_benefits || 0), 0)
    const totalRTO         = rows.reduce((s, r) => s + (r.rto_units || 0), 0)
    const totalRVP         = rows.reduce((s, r) => s + (r.rvp_units || 0), 0)
    const totalCancelled   = rows.reduce((s, r) => s + (r.cancelled_units || 0), 0)

    const sortedByVar = [...matched].sort((a, b) => b.variance_bs - a.variance_bs)
    const varianceChartData = [
      ...sortedByVar.filter(r => r.variance_bs < 0).slice(-6),
      ...sortedByVar.filter(r => r.variance_bs > 0).slice(0, 6),
    ].map(r => ({
      name:     r.platform_sku_name.split('-').slice(-2).join('-'),
      fullName: r.platform_sku_name,
      variance: Math.round(r.variance_bs),
    }))

    const marginBrackets = [
      { label: 'Loss',   count: rows.filter(r => (r.net_margin_pct||0) < 0).length,                                  color: '#ef4444' },
      { label: '0–20%',  count: rows.filter(r => (r.net_margin_pct||0) >= 0  && (r.net_margin_pct||0) < 20).length, color: '#f97316' },
      { label: '20–50%', count: rows.filter(r => (r.net_margin_pct||0) >= 20 && (r.net_margin_pct||0) < 50).length, color: '#eab308' },
      { label: '50–80%', count: rows.filter(r => (r.net_margin_pct||0) >= 50 && (r.net_margin_pct||0) < 80).length, color: '#22c55e' },
      { label: '80%+',   count: rows.filter(r => (r.net_margin_pct||0) >= 80).length,                               color: '#16a34a' },
    ]

    const beatingSkus = matched.filter(r => r.variance_bs > 0)
    const missingSkus = matched.filter(r => r.variance_bs < 0)

    return {
      totalActualBS, totalExpectedBS, netVariance,
      totalRevShipping, totalCommission, totalCollection, totalGST, totalTax, totalRewards,
      totalRTO, totalRVP, totalCancelled,
      varianceChartData, marginBrackets,
      beatingCount: beatingSkus.length,
      missingCount: missingSkus.length,
      beatingTotal: beatingSkus.reduce((s, r) => s + r.variance_bs, 0),
      missingTotal: missingSkus.reduce((s, r) => s + r.variance_bs, 0),
    }
  }, [report])

  return { augmentedRows, insightsData }
}

import { useMemo } from 'react'

/**
 * Derives all computed fields for a platform P&L report.
 * Platform-generic: works for Flipkart, Meesho, and any future platform
 * because FK-specific fields (commission, fixed_fee, taxes_gst, rewards) are
 * simply 0/null for other platforms — feesPerUnit still sums correctly.
 *
 *   augmentedRows: matched SKU rows + per-unit cost/variance/margin fields
 *   insightsData:  aggregate totals + chart data for the Insights tab
 */
export function useReportData(report) {
  const augmentedRows = useMemo(() => {
    const matched = (report?.sku_rows || []).filter(r => r.is_matched)
    return matched.map(r => {
      const fkBsPerUnit = (r.bank_settlement_projected != null && r.net_units)
        ? r.bank_settlement_projected / r.net_units : null
      const varPerUnit = (fkBsPerUnit != null && r.casper_breakeven != null)
        ? fkBsPerUnit - r.casper_breakeven : null
      const varTotal = (varPerUnit != null && r.net_units != null)
        ? varPerUnit * r.net_units : null
      const feesPerUnit = r.net_units ? (
        (Math.abs(r.commission_fee || 0) + Math.abs(r.collection_fee || 0) +
         Math.abs(r.fixed_fee || 0) +
         Math.abs(r.taxes_gst || 0) + Math.abs(r.taxes_tcs || 0) + Math.abs(r.taxes_tds || 0)
         - Math.abs(r.rewards_benefits || 0)) / r.net_units
      ) : null
      const totalEarned   = r.bank_settlement_projected ?? null
      const expectedTotal = (r.casper_breakeven != null && r.net_units != null)
        ? r.casper_breakeven * r.net_units : null

      const profitNoGst = (fkBsPerUnit != null && r.casper_breakeven != null)
        ? fkBsPerUnit - r.casper_breakeven : null
      const profitWithGst = (fkBsPerUnit != null && r.casper_breakeven_gst != null)
        ? fkBsPerUnit - r.casper_breakeven_gst : null
      const realMarginPct = (fkBsPerUnit != null && r.casper_breakeven)
        ? ((fkBsPerUnit - r.casper_breakeven) / r.casper_breakeven) * 100 : null
      const marginGstPct = (fkBsPerUnit != null && r.casper_breakeven_gst)
        ? ((fkBsPerUnit - r.casper_breakeven_gst) / r.casper_breakeven_gst) * 100 : null

      return {
        ...r,
        fk_bs_per_unit: fkBsPerUnit,
        true_profit_per_unit: varPerUnit,
        total_true_profit: varTotal,
        fees_per_unit: feesPerUnit,
        total_earned: totalEarned,
        expected_total: expectedTotal,
        profit_no_gst: profitNoGst,
        profit_with_gst: profitWithGst,
        real_margin_pct: realMarginPct,
        margin_gst_pct: marginGstPct,
      }
    })
  }, [report])

  const insightsData = useMemo(() => {
    if (!report) return null
    const rows    = report.sku_rows || []
    const matched = rows.filter(r => r.is_matched && r.variance_bs != null)
    const totalActualBS    = matched.reduce((s, r) => s + (r.bank_settlement_projected || 0), 0)
    const totalExpectedBS  = matched.reduce((s, r) => s + (r.casper_expected_bs || 0) * (r.net_units || 0), 0)
    const netVariance      = totalActualBS - totalExpectedBS
    const totalRevShipping = rows.reduce((s, r) => s + Math.abs(r.reverse_shipping_fee || 0), 0)
    const totalCommission  = rows.reduce((s, r) => s + Math.abs(r.commission_fee || 0), 0)
    const totalCollection  = rows.reduce((s, r) => s + Math.abs(r.collection_fee || 0), 0)
    const totalGST         = rows.reduce((s, r) => s + Math.abs(r.taxes_gst || 0), 0)
    const totalTax         = rows.reduce((s, r) => s + Math.abs(r.taxes_tcs || 0) + Math.abs(r.taxes_tds || 0), 0)
    const totalRewards     = rows.reduce((s, r) => s + (r.rewards_benefits || 0), 0)
    const totalRTO         = rows.reduce((s, r) => s + (r.rto_units || 0), 0)
    const totalRVP         = rows.reduce((s, r) => s + (r.rvp_units || 0), 0)
    const totalCancelled   = rows.reduce((s, r) => s + (r.cancelled_units || 0), 0)

    const sortedByVar = [...matched].sort((a, b) => b.variance_bs - a.variance_bs)
    const varianceChartData = [
      ...sortedByVar.filter(r => r.variance_bs < 0).slice(-6),
      ...sortedByVar.filter(r => r.variance_bs > 0).slice(0, 6),
    ].map(r => ({
      name:     r.platform_sku_name.split('-').slice(-2).join('-'),
      fullName: r.platform_sku_name,
      variance: Math.round(r.variance_bs),
    }))

    const marginBrackets = [
      { label: 'Loss',   count: rows.filter(r => (r.net_margin_pct||0) < 0).length,                                  color: '#ef4444' },
      { label: '0–20%',  count: rows.filter(r => (r.net_margin_pct||0) >= 0  && (r.net_margin_pct||0) < 20).length, color: '#f97316' },
      { label: '20–50%', count: rows.filter(r => (r.net_margin_pct||0) >= 20 && (r.net_margin_pct||0) < 50).length, color: '#eab308' },
      { label: '50–80%', count: rows.filter(r => (r.net_margin_pct||0) >= 50 && (r.net_margin_pct||0) < 80).length, color: '#22c55e' },
      { label: '80%+',   count: rows.filter(r => (r.net_margin_pct||0) >= 80).length,                               color: '#16a34a' },
    ]

    const beatingSkus = matched.filter(r => r.variance_bs > 0)
    const missingSkus = matched.filter(r => r.variance_bs < 0)

    return {
      totalActualBS, totalExpectedBS, netVariance,
      totalRevShipping, totalCommission, totalCollection, totalGST, totalTax, totalRewards,
      totalRTO, totalRVP, totalCancelled,
      varianceChartData, marginBrackets,
      beatingCount: beatingSkus.length,
      missingCount: missingSkus.length,
      beatingTotal: beatingSkus.reduce((s, r) => s + r.variance_bs, 0),
      missingTotal: missingSkus.reduce((s, r) => s + r.variance_bs, 0),
    }
  }, [report])

  return { augmentedRows, insightsData }
}

// Shared formatters for Flipkart P&L views.

export const fmt = (v, d = 0) => {
  if (v == null) return '—'
  const n = Number(v)
  const abs = Math.abs(n).toLocaleString('en-IN', { minimumFractionDigits: d, maximumFractionDigits: d })
  return (n < 0 ? '-' : '') + '₹' + abs
}

export const fmtN   = v => v == null ? '—' : Number(v).toLocaleString('en-IN')
export const fmtPct = v => v == null ? '—' : Number(v).toFixed(1) + '%'

const parseLocalDate = s => s ? new Date(s + 'T00:00:00') : null

export const fmtPeriod = (start, end) => {
  const s = parseLocalDate(start), e = parseLocalDate(end)
  if (!s || !e) return '—'
  return `${s.toLocaleDateString('en-IN', { month: 'short', year: 'numeric' })} — ${e.toLocaleDateString('en-IN', { day: 'numeric', month: 'short', year: 'numeric' })}`
}

import { useState, useEffect } from 'react'
import { useParams, useNavigate } from 'react-router-dom'
import { getSkus, getPlatforms, getPricingForSku, createPricing, updatePricing, deletePricing, inCompany, errText } from '../api/client'
import { useCompany } from '../context/CompanyContext'
import './Pricing.css'

function Toast({ msg, type, onClose }) {
  useEffect(() => { const t = setTimeout(onClose, 3000); return () => clearTimeout(t) }, [])
  return <div className={`toast toast-${type}`}>{msg}</div>
}

const EMPTY = {
  platform_id: '', price: '', package: '', logistics: '',
  addons: 0, cr_percentage: 10, cr_cost: '',
  damage_percentage: 15, damage_cost: '', misc_total: '', gst: 0,
}

function PricingCard({ row, platform, onEdit, onDelete }) {
  return (
    <div className="pricing-card">
      <div className="pc-header">
        <span className="pc-platform">{platform?.name ?? 'Unknown'}</span>
        <span className={`badge ${row.is_active ? 'badge-green' : 'badge-red'}`}>
          {row.is_active ? 'Active' : 'Inactive'}
        </span>
      </div>

      <div className="pc-grid">
        {[
          ['Price',     `₹${row.price}`],
          ['Package',   `₹${row.package}`],
          ['Logistics', `₹${row.logistics}`],
          ['Addons',    `₹${row.addons}`],
          ['Misc',      `₹${row.misc_total}`],
          ['CR Cost',   `₹${row.cr_cost}`, `${row.cr_percentage}%`],
          ['Damage',    `₹${row.damage_cost}`, `${row.damage_percentage}%`],
          ['GST',       `₹${row.gst}`],
        ].map(([label, val, sub]) => (
          <div key={label} className="pc-cell">
            <div className="pc-cell-label">{label}</div>
            <div className="pc-cell-value mono">{val}</div>
            {sub && <div className="pc-cell-sub">{sub}</div>}
          </div>
        ))}
      </div>

      <div className="pc-results">
        <div className="pc-result">
          <span className="pc-result-label">Breakeven</span>
          <span className="pc-result-value mono">₹{row.breakeven}</span>
        </div>
        <div className="pc-result pc-result--gold">
          <span className="pc-result-label">Bank Settlement</span>
          <span className="pc-result-value mono gold">₹{row.bank_settlement}</span>
        </div>
      </div>

      <div className="pc-actions">
        <button className="btn btn-ghost btn-sm" onClick={() => onEdit(row)}>Edit</button>
        <button className="btn btn-danger btn-sm" onClick={() => onDelete(row)}>Remove</button>
      </div>
    </div>
  )
}

export default function Pricing() {
  const { skuId }    = useParams()
  const navigate     = useNavigate()
  // A SKU already belongs to one company, so once it's picked, creating pricing
  // for it can target that company directly — no separate picker needed, unlike
  // ledger/billing where a blank record has nothing to infer a company from.
  const { companies, isAll } = useCompany()
  const companyName = id => companies.find(c => c.id === id)?.name
  const [skus, setSkus]           = useState([])
  const [platforms, setPlatforms] = useState([])
  const [rows, setRows]           = useState([])
  const [selectedSku, setSelectedSku] = useState(skuId ? parseInt(skuId) : '')
  const [loading, setLoading]     = useState(false)
  const [modal, setModal]         = useState(null)
  const [form, setForm]           = useState(EMPTY)
  const [editId, setEditId]       = useState(null)
  const [saving, setSaving]       = useState(false)
  const [toast, setToast]         = useState(null)
  const [deleteConfirm, setDeleteConfirm] = useState(null)

  const showToast = (msg, type = 'success') => setToast({ msg, type })

  useEffect(() => {
    Promise.all([getSkus(), getPlatforms()])
      .then(([s, p]) => { setSkus(s); setPlatforms(p) })
  }, [])

  const loadPricing = (id) => {
    if (!id) { setRows([]); return }
    setLoading(true)
    getPricingForSku(id).then(setRows).finally(() => setLoading(false))
  }

  useEffect(() => { loadPricing(selectedSku) }, [selectedSku])

  const handleSkuChange = (id) => {
    setSelectedSku(id ? parseInt(id) : '')
    navigate(id ? `/pricing/${id}` : '/pricing')
  }

  const openCreate = () => { setForm(EMPTY); setEditId(null); setModal('create') }
  const openEdit = (row) => {
    setForm({
      platform_id: row.platform_id, price: row.price,
      package: row.package, logistics: row.logistics,
      addons: row.addons, cr_percentage: row.cr_percentage,
      cr_cost: row.cr_cost, damage_percentage: row.damage_percentage,
      damage_cost: row.damage_cost, misc_total: row.misc_total, gst: row.gst,
    })
    setEditId(row.id)
    setModal('edit')
  }

  const handleSave = async () => {
    setSaving(true)
    try {
      const payload = {
        sku_id:            parseInt(selectedSku),
        platform_id:       parseInt(form.platform_id),
        price:             parseFloat(form.price),
        package:           parseFloat(form.package),
        logistics:         parseFloat(form.logistics),
        addons:            parseFloat(form.addons) || 0,
        cr_percentage:     parseFloat(form.cr_percentage),
        damage_percentage: parseFloat(form.damage_percentage),
        gst:               parseFloat(form.gst) || 0,
        ...(form.cr_cost     !== '' && { cr_cost:     parseFloat(form.cr_cost) }),
        ...(form.damage_cost !== '' && { damage_cost: parseFloat(form.damage_cost) }),
        ...(form.misc_total  !== '' && { misc_total:  parseFloat(form.misc_total) }),
      }
      if (modal === 'create') {
        // In All Companies the request header is 'all', which the backend refuses
        // for writes — override it with the company the selected SKU already belongs to.
        await createPricing(payload, isAll ? inCompany(currentSku.company_id) : undefined)
        showToast('Pricing created — auto-calculated!')
      } else {
        await updatePricing(editId, payload)
        showToast('Pricing updated & recalculated!')
      }
      setModal(null)
      loadPricing(selectedSku)
    } catch (err) {
      showToast(errText(err, 'Error saving'), 'error')
    } finally {
      setSaving(false)
    }
  }

  const handleDelete = async (row) => {
    try {
      await deletePricing(row.id)
      showToast('Pricing removed')
      setDeleteConfirm(null)
      loadPricing(selectedSku)
    } catch (err) {
      showToast(errText(err, 'Error deleting'), 'error')
    }
  }

  const currentSku      = skus.find(s => s.id === parseInt(selectedSku))
  const pricedPlatforms = new Set(rows.map(r => r.platform_id))

  return (
    <div className="pricing-page">
      {toast && <Toast msg={toast.msg} type={toast.type} onClose={() => setToast(null)} />}

      <div className="page-header">
        <div>
          <h1 className="page-title">Pricing</h1>
          <p className="page-subtitle">Auto-calculates breakeven, profit & bank settlement</p>
        </div>
        {selectedSku && (
          <button className="btn btn-gold" onClick={openCreate}>+ Add Platform</button>
        )}
      </div>

      {/* SKU Selector */}
      <div className="card sku-selector">
        <div style={{ display:'flex', alignItems:'center', gap:16, flexWrap:'wrap' }}>
          <label style={{ fontSize:12, fontWeight:700, color:'var(--text-2)', letterSpacing:'0.05em', textTransform:'uppercase', whiteSpace:'nowrap' }}>
            Select SKU
          </label>
          <select className="input" style={{ maxWidth:420 }} aria-label="Select SKU"
            value={selectedSku} onChange={e => handleSkuChange(e.target.value)}>
            <option value="">— Choose a SKU —</option>
            {skus.filter(s => s.is_active).map(s => (
              <option key={s.id} value={s.id}>
                {s.shringar_sku}{s.description ? ` — ${s.description}` : ''}
                {/* In All Companies the same SKU code can exist in more than one
                    company — name which one this row is, so picking is unambiguous. */}
                {isAll && companyName(s.company_id) ? ` (${companyName(s.company_id)})` : ''}
              </option>
            ))}
          </select>
          {currentSku && (
            <span className="mono" style={{ color:'var(--gold)', fontSize:13 }}>
              {currentSku.vendor?.name && `· ${currentSku.vendor.name}`}
            </span>
          )}
        </div>
      </div>

      {/* Pricing cards or empty state */}
      {selectedSku && (
        loading ? (
          <div className="loader-page"><div className="loader" style={{ width:32, height:32 }} /></div>
        ) : rows.length === 0 ? (
          <div className="empty-state">
            <div className="empty-icon">◆</div>
            <div className="empty-title">No pricing yet</div>
            <p className="empty-sub">Add a platform to calculate breakeven and bank settlement</p>
            <button className="btn btn-gold" onClick={openCreate} style={{ marginTop:16 }}>
              + Add Platform Pricing
            </button>
          </div>
        ) : (
          <div className="pricing-grid">
            {rows.map(row => (
              <PricingCard key={row.id} row={row}
                platform={platforms.find(p => p.id === row.platform_id)}
                onEdit={openEdit} onDelete={setDeleteConfirm} />
            ))}
          </div>
        )
      )}

      {/* Formula reference (shown when no SKU selected) */}
      {!selectedSku && (
        <div className="card formula-card">
          <div className="formula-title">Pricing Formula Reference</div>
          {[
            ['CR Cost',         'platform.cr_charge × (cr_percentage / 100)'],
            ['Damage Cost',     'price × (damage_percentage / 100)'],
            ['Breakeven',       'price + package + logistics + addons + misc + cr_cost + damage_cost'],
            ['Net Profit',      'breakeven × (profit_percentage / 100)'],
            ['BS w/o GST',      'round(breakeven + net_profit)'],
            ['Bank Settlement', 'bs_wo_gst + round(bs_wo_gst × gst_rate / 100)'],
          ].map(([name, formula]) => (
            <div key={name} className="formula-row">
              <span className="formula-name">{name}</span>
              <span className="formula-eq mono">{formula}</span>
            </div>
          ))}
        </div>
      )}

      {/* Add / Edit Modal */}
      {modal && (
        <div className="overlay" onClick={e => e.target === e.currentTarget && setModal(null)}>
          <div className="modal" style={{ maxWidth:560 }}>
            <div className="modal-title">
              {modal === 'create' ? 'Add Platform Pricing' : 'Edit Pricing'}
            </div>

            {currentSku && (
              <div style={{ marginBottom:18, padding:'8px 12px', background:'var(--surface-2)', borderRadius:'var(--radius-sm)', fontSize:13 }}>
                <span style={{ color:'var(--text-3)' }}>SKU: </span>
                <span className="mono" style={{ color:'var(--gold)' }}>{currentSku.shringar_sku}</span>
              </div>
            )}

            <div className="form-grid">
              <div className="input-group span-2">
                <label>Platform *</label>
                <select className="input" value={form.platform_id} aria-label="Platform"
                  onChange={e => setForm(f => ({ ...f, platform_id: e.target.value }))}>
                  <option value="">— Select Platform —</option>
                  {platforms.filter(p => p.is_active).map(p => (
                    <option key={p.id} value={p.id}
                      disabled={modal === 'create' && pricedPlatforms.has(p.id)}>
                      {p.name} — CR ₹{p.cr_charge}
                      {modal === 'create' && pricedPlatforms.has(p.id) ? ' (already priced)' : ''}
                    </option>
                  ))}
                </select>
              </div>

              <div className="input-group">
                <label>Price (₹) *</label>
                <input className="input mono" type="number" placeholder="64"
                  value={form.price} onChange={e => setForm(f => ({ ...f, price: e.target.value }))} />
              </div>
              <div className="input-group">
                <label>Packaging (₹) *</label>
                <input className="input mono" type="number" placeholder="7"
                  value={form.package} onChange={e => setForm(f => ({ ...f, package: e.target.value }))} />
